-(void) closesidewindow
{
    [self adjustpresentingviewwidthwithwidth:0];
}

- (void)panGestureDetected:(UIPanGestureRecognizer *)recognizer
{
    if (attendanceringview) {
        
        UIView *windowview = self.view;
        while (windowview.superview != Nil) {
            windowview = windowview.superview;
        }
        
        if (recognizer.state!=UIGestureRecognizerStateEnded) {
            CGPoint point= [recognizer locationInView:windowview];
            point.x=point.x-attendanceringview.frame.origin.x;
            point.y=point.y-attendanceringview.frame.origin.y;
            lasttouchedsector= [MyClass updateattendanceringwithtouchpoint:point attendanceringview:attendanceringview attendancebuttonarray:attendancebuttonarray lasttouchedsector:lasttouchedsector size:@"small"];
        }else{
            CGPoint point= [recognizer locationInView:windowview];
            point.x=point.x-attendanceringview.frame.origin.x;
            point.y=point.y-attendanceringview.frame.origin.y;
            
            [self attendanceringreleasedwithtouchpoint:point];
            
            [UIView animateWithDuration:0.4 animations:^{attendanceringview.alpha = 0.0;} completion:^(BOOL finished){ [attendanceringview removeFromSuperview]; }];
            attendanceringview=nil;
            DetailLessonTable.scrollEnabled=TRUE;
            [DetailLessonTable deselectRowAtIndexPath:[DetailLessonTable indexPathForSelectedRow] animated: YES];
        }
    }
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gestureRecognizer shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)otherGestureRecognizer
{
    return YES;
}


-(void) attendanceringreleasedwithtouchpoint:(CGPoint)touchpoint
{
    //check if inside ring
    if ([MyClass returntouchpointwithinattendanceringwithtouchpoint:touchpoint size:@"small"]) {
        NSIndexPath *selectedIndexPath = [DetailLessonTable indexPathForSelectedRow];
        [self updateattendancewithindexpath:selectedIndexPath value:((AttendanceButtonObject *)[attendancebuttonarray objectAtIndex:lasttouchedsector]).buttonname];
    }
    disableclassdelete=FALSE;
}

-(void)updateattendancewithindexpath:(NSIndexPath *)indexpath value:(NSString *)value
{

    if (selectedattendancebuttontag==1105) {
        if (![value isEqualToString:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).attendance]) {
            NSString *defaultleavenaturelistkey=[MyClass returnDefaultLeaveNatureListKeyWithAttendance:value];
            
            if ([((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).attendance isEqualToString:@"Extend"]) {
                //NSString *classhasextendedclass=[[MyClass classhasextendedclasswithclasskey:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).classkey enrollmentkey:nil] objectForKey:@"tocount"];
                if([self hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).classkey FreeScheduleClassarray:FreeScheduleClassArray]){
                //if ([classhasextendedclass intValue]>0) {
                    UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Attendance"] message:[MyClass returntitlewithtitle:@"This class time has been used to extend other class"] preferredStyle:UIAlertControllerStyleAlert];
                    
                    UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                        [missinginput dismissViewControllerAnimated:YES completion:nil];
                    }];
                    
                    [missinginput addAction:OKAction];
                    //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
                    
                    return;
                    
                }
            }else /*if ([value isEqualToString:@"Makeup"] || [value isEqualToString:@"Makeup"] || [value isEqualToString:@"Makeup"]){*/
                if ([self extraQuotaRequiredWithNewLeaveNatureListKey:defaultleavenaturelistkey attendance:value] && ![self isOneQuotaAvailable]){
                    
                    UIAlertController *alert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Attendance"] message:[MyClass returntitlewithtitle:@"Leave quota are used up. Do you want to continue?"] preferredStyle:UIAlertControllerStyleAlert];
                    
                    UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                        [self updatefreescheduleclassobject:[FreeScheduleClassArray objectAtIndex:indexpath.row] classdate:nil classtime:nil instructor:nil classroom:nil attendance:value makeupdate:@"" makeuptime:@"" makeupinstructor:@"" makeupclassroom:@"" makeupattendance:[value isEqualToString:@"Makeup"]?globalvariables.centerrecord.defaultattendancestatus:@"" leavenaturelistkey:defaultleavenaturelistkey sinstructor:nil makeupsinstructor:@"" sortschedule:YES];
                        [DetailLessonTable reloadData];
                    }];
                    
                    UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                        [alert dismissViewControllerAnimated:YES completion:nil];
                    }];
                    
                    [alert addAction:OKAction];
                    [alert addAction:CancelAction];
                    //[self presentViewController:alert animated:YES completion:nil];
                    [MyClass presentViewController:alert View:self];
                    
            }else{
                
                [self updatefreescheduleclassobject:[FreeScheduleClassArray objectAtIndex:indexpath.row] classdate:nil classtime:nil instructor:nil classroom:nil attendance:value makeupdate:@"" makeuptime:@"" makeupinstructor:@"" makeupclassroom:@"" makeupattendance:[value isEqualToString:@"Makeup"]?globalvariables.centerrecord.defaultattendancestatus:@"" leavenaturelistkey:defaultleavenaturelistkey sinstructor:nil makeupsinstructor:@"" sortschedule:YES];
                [DetailLessonTable reloadData];
            }
            

        }
    }else{
        if (![value isEqualToString:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).makeupattendance]) {
            //((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexpath.row]).makeupattendance=value;
            [self updatefreescheduleclassobject:[FreeScheduleClassArray objectAtIndex:indexpath.row] classdate:nil classtime:nil instructor:nil classroom:nil attendance:nil makeupdate:nil makeuptime:nil makeupinstructor:nil makeupclassroom:nil makeupattendance:value leavenaturelistkey:nil sinstructor:nil makeupsinstructor:nil sortschedule:YES];
            [DetailLessonTable reloadData];
        }
    }
    //[self storeTmpField];
    [EnrollmentPopoverTable reloadData];
    [self showsidewindowwithwindow:@"showDetailLesson"];
    [self adjusttablesize];
}

-(NSString *) returnEnrollmentDefaultAttendanceWithDay:(NSString *)startdate
{
    if(globalvariables.centerrecord.usereserveddayduringenrollment && globalvariables.centerrecord.markenrollmentreserveddaytomakeup && ![startdate isEqualToString:@"TBD"] && [MyClass isReservedDay:[MyClass convertDateFormatWithDate:startdate FromDateFormat:@"dd-MMM-yyyy" ToDateFormat:@"yyyy-MM-dd" Translate:NO]]){
        return @"Makeup";
    }
    return globalvariables.centerrecord.defaultattendancestatus;
}

