    [ScheduleTable reloadData];
    //[self adjusttablesize];
    [self createDetailLessonToolBar];
    
    [self adjusttablesize];
}

-(BOOL) isEndDateUnknown
{
    BOOL skipmakeupforrenewal=((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).skipmakeupforrenewal;
    
    if ([PopoverEnrollment.enddate isEqualToString:@"TBD"] || ([PopoverEnrollment.enddate isEqualToString:@"TBF"] && !globalvariables.centerrecord.renewevenifthereistbdclass)) {
        return YES;
    }else{
        if (!skipmakeupforrenewal) {
            if ([self hasMakeupdateTBDwithFreeScheduleClassArray:FreeScheduleClassArray]) {
                if (!globalvariables.centerrecord.renewevenifthereistbdclass) {
                    return YES;
                }
            }
        }
    }
    return NO;
}


- (IBAction)renewalButtonPressed:(id)sender {

    
    if(![((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).status isEqualToString:@"Active"]){
        UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Renew Enrollment"] message:[MyClass returntitlewithtitle:@"Renew failed because course is inactive"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [erroralert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [erroralert addAction:OKAction];
        [self presentViewController:erroralert animated:YES completion:nil];
    }else if (![self isEndDateUnknown]) {

        if (![self determinelastclassinstructorandtimeandclassroomanddate]) {
            return;
        }

        EnrollmentTableMode=@"Renewal";
        [self InitializeFieldWithEnrollmentTableMode:EnrollmentTableMode];
        
        [self createEditBarButtonwithDraftOption:YES];
        

        
        workingEnrollment.paymentrecords=[[NSMutableArray alloc]init];

        [EnrollmentPopoverTable reloadData];
        [self adjusttablesize];
    }else{
        UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Renew Enrollment"] message:[MyClass returntitlewithtitle:@"Renew failed because there is TBD class"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [erroralert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [erroralert addAction:OKAction];
        [self presentViewController:erroralert animated:YES completion:nil];
    }
    
}

-(int) returnnumberofoutstandingclass
{
    int count=0;
    TransferFreeScheduleClassArray=[[NSMutableArray alloc]init];
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
        if (![FreeScheduleClassObject.action isEqualToString:@"Delete"]) {
            if ([FreeScheduleClassObject.attendance isEqualToString:@"Makeup"]) {
                if([self isFutureDateWithDate:FreeScheduleClassObject.makeupdate Time:FreeScheduleClassObject.makeuptime]){
                    count+=1;;
                }else{
                    [TransferFreeScheduleClassArray addObject:FreeScheduleClassObject];
                }
            }else if ([FreeScheduleClassObject.attendance isEqualToString:@"Extend"]) {
                if (![self hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:FreeScheduleClassObject.classkey FreeScheduleClassarray:FreeScheduleClassArray]) {
                    if([self isFutureDateWithDate:FreeScheduleClassObject.classdate Time:FreeScheduleClassObject.classtime]){
                        count+=1;
                    }else{
                        [TransferFreeScheduleClassArray addObject:FreeScheduleClassObject];
                    }
                }else{
                    [TransferFreeScheduleClassArray addObject:FreeScheduleClassObject];
                }
            }else{
                if([self isFutureDateWithDate:FreeScheduleClassObject.classdate Time:FreeScheduleClassObject.classtime]){
                    count+=1;
                }else{
                    [TransferFreeScheduleClassArray addObject:FreeScheduleClassObject];
                }
            }
        }
    }
    return count;
}

-(void) deleteFutureClass
{
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
        if ([FreeScheduleClassObject.attendance isEqualToString:@"Makeup"]) {
            if (![FreeScheduleClassObject.makeupdate isEqualToString:@""] || ![FreeScheduleClassObject.makeupdate isEqualToString:@"TBD"]) {
                if([self isFutureDateWithDate:FreeScheduleClassObject.makeupdate Time:FreeScheduleClassObject.makeuptime]){
                    FreeScheduleClassObject.action=@"Delete";
                }
            }
        }else{
            if([self isFutureDateWithDate:FreeScheduleClassObject.classdate Time:FreeScheduleClassObject.classtime]){
                FreeScheduleClassObject.action=@"Delete";
            }
        }
    }
}

-(BOOL) isFutureDateWithDate:(NSString *)date Time:(NSString *)time
{
    if ([date isEqualToString:@"TBD"] || [time isEqualToString:@"TBD"]|| [date isEqualToString:@""] || [time isEqualToString:@""]) {
        return TRUE;
    }else if ([[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ %@",date,time] DateFormat:@"dd-MMM-yyyy HH:mm"] compare:[NSDate date]]==NSOrderedDescending){
        return TRUE;
    }
    return FALSE;
}

-(NSString *) calculateTransferFeewithOutstandingClass:(int)outstandingclass
{
    NSString *newTuitionFee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:tmpLevel noOfClass:[NSString stringWithFormat:@"%i",[workingEnrollment.noofclass intValue]-outstandingclass] startdatetime:tmpStartDateTime freescheduleclassarray:TransferFreeScheduleClassArray];
    

    
    float discountedfee=[newTuitionFee floatValue];
    NSString *tmp_TotalDiscount;
    
    for (int i=0; i<workingEnrollment.promotiondiscountrecords.count; i++) {
        marketingobject=[workingEnrollment.promotiondiscountrecords objectAtIndex:i];
        if (![marketingobject.promotionfixeddiscount isEqualToString:@""]) {
            discountedfee-=[marketingobject.promotionfixeddiscount floatValue]*(!marketingobject.perclassorquantity?1:[workingEnrollment.noofclass integerValue]-outstandingclass);
        }else{
            discountedfee*=(1-[marketingobject.promotionpercentagediscount floatValue]/100);
        }
    }
    
    discountedfee*=(1-[workingEnrollment.oneoffpercentagediscount floatValue]/100);
    discountedfee-=[workingEnrollment.oneoffdiscount floatValue];
    //discountedfee-=[tmpManualRecursiveFixedDiscount floatValue];
    
    tmp_TotalDiscount=[NSString stringWithFormat:@"%g",[newTuitionFee floatValue]-(globalvariables.centerrecord.noofroundoffdigit==0?lroundf(discountedfee):discountedfee)];
    
    if (noofroundoffdigit==1) {
        if ([tmp_TotalDiscount floatValue]==(int)[tmp_TotalDiscount floatValue]) {
            tmp_TotalDiscount=[NSString stringWithFormat:@"%g",[tmp_TotalDiscount floatValue]];
        }else{
            if ([[NSString stringWithFormat:@"%.1f",[tmp_TotalDiscount floatValue]] hasSuffix:@".0"]) {
                tmp_TotalDiscount= [[NSString stringWithFormat:@"%.1f",[tmp_TotalDiscount floatValue]] substringToIndex:[[NSString stringWithFormat:@"%.1f",[tmp_TotalDiscount floatValue]] length]-2];
            }else{
                tmp_TotalDiscount= [NSString stringWithFormat:@"%.1f",[tmp_TotalDiscount floatValue]];
            }
        }
    }else{
        tmp_TotalDiscount=[NSString stringWithFormat:@"%ld",lroundf([tmp_TotalDiscount floatValue])];
    }
    
    float thetotalfee=0;
    NSString *newtotalfee;
    
    thetotalfee=[newTuitionFee floatValue]-[tmp_TotalDiscount floatValue]+[workingEnrollment.enrollmentfee floatValue]+[workingEnrollment.latefee floatValue];
    
    if (noofroundoffdigit==1) {
        if (thetotalfee==(int)thetotalfee) {
            newtotalfee=[NSString stringWithFormat:@"%g",thetotalfee];
        }else{
            if ([[NSString stringWithFormat:@"%.1f",thetotalfee] hasSuffix:@".0"]) {
                newtotalfee= [[NSString stringWithFormat:@"%.1f",thetotalfee] substringToIndex:[[NSString stringWithFormat:@"%.1f",thetotalfee] length]-2];
            }else{
                newtotalfee= [NSString stringWithFormat:@"%.1f",thetotalfee];
            }
        }
        
        float transferfee=[workingEnrollment.paid floatValue]-[newtotalfee floatValue];
        
        if (transferfee==(int)transferfee) {
            return [NSString stringWithFormat:@"%g",transferfee];
        }else{
            if ([[NSString stringWithFormat:@"%.1f",transferfee] hasSuffix:@".0"]) {
                return [[NSString stringWithFormat:@"%.1f",transferfee] substringToIndex:[[NSString stringWithFormat:@"%.1f",transferfee] length]-2];
            }else{
                return [NSString stringWithFormat:@"%.1f",transferfee];
            }
        }
        
    }else{
        newtotalfee=[NSString stringWithFormat:@"%ld",lroundf(thetotalfee)];
        return [NSString stringWithFormat:@"%ld",lroundf([workingEnrollment.paid floatValue]-[newtotalfee floatValue])];
    }

}

