-(void) transferEnrollmentRecord
{
    
    [self.view endEditing:YES];
    
    UIAlertController *transferenrollmentalert;
    int outstandingclass=[self returnnumberofoutstandingclass];

    
    if (outstandingclass==[workingEnrollment.noofclass intValue]) {
        if (workingEnrollment.paymentrecords.count>0) {
            //void with full refund
            
            transferenrollmentalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[NSString stringWithFormat:@"%@%@%@",[MyClass returntitlewithtitle:@"Are you sure to void the current enrollment and transfer $"],workingEnrollment.paid,[MyClass returntitlewithtitle:@" to other course?"]] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                
                if (![workingEnrollment.outstandingmakeupclasses isEqualToString:@""]) {
                    UIAlertController *makeupalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[NSString stringWithFormat:@"%@\r\n\r\n%@",[MyClass returntitlewithtitle:@"There are makeup for the cancelled classes, do you want to proceed?"],workingEnrollment.outstandingmakeupclasses] preferredStyle:UIAlertControllerStyleAlert];
                    
                    UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                        [self voidandtransfercourse];
                    }];
                    
                    UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                        [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
                    }];
                    
                    [makeupalert addAction:OKAction];
                    [makeupalert addAction:CancelAction];
                    
                    [MyClass presentViewController:makeupalert View:self];
                }else{
                    [self voidandtransfercourse];
                }
            }];
            
            UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [transferenrollmentalert addAction:OKAction];
            [transferenrollmentalert addAction:CancelAction];
            
            [MyClass presentViewController:transferenrollmentalert View:self];
            
            
        }else{
            //delete
            transferenrollmentalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[MyClass returntitlewithtitle:@"Are you sure to delete the current enrollment and enroll another course?"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                if (![workingEnrollment.outstandingmakeupclasses isEqualToString:@""]) {
                    UIAlertController *makeupalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[NSString stringWithFormat:@"%@\r\n\r\n%@",[MyClass returntitlewithtitle:@"There are makeup for the cancelled classes, do you want to proceed?"],workingEnrollment.outstandingmakeupclasses] preferredStyle:UIAlertControllerStyleAlert];
                    
                    UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                        [self deleteandenrollcourse];
                    }];
                    
                    UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                        [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
                    }];
                    
                    [makeupalert addAction:OKAction];
                    [makeupalert addAction:CancelAction];
                    
                    [MyClass presentViewController:makeupalert View:self];
                }else{
                    [self deleteandenrollcourse];
                }

                
            }];
            
            UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [transferenrollmentalert addAction:OKAction];
            [transferenrollmentalert addAction:CancelAction];
            
            //[self presentViewController:transferenrollmentalert animated:YES completion:nil];
            [MyClass presentViewController:transferenrollmentalert View:self];
        }
    }else{
        //refund
        NSString *transferfee=[self calculateTransferFeewithOutstandingClass:outstandingclass];
        transferenrollmentalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[NSString stringWithFormat:@"%@%i%@%@%@",[MyClass returntitlewithtitle:@"Are you sure to cancel the "],outstandingclass,[MyClass returntitlewithtitle:@" remaining lesson(s) and transfer $"],transferfee,[MyClass returntitlewithtitle:@" to other course?"]] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
            if (![workingEnrollment.outstandingmakeupclasses isEqualToString:@""]) {
                UIAlertController *makeupalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Transfer_Course"] message:[NSString stringWithFormat:@"%@\r\n\r\n%@",[MyClass returntitlewithtitle:@"There are makeup for the cancelled classes, do you want to proceed?"],workingEnrollment.outstandingmakeupclasses] preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                    [self cancelandtransfercourse];
                }];
                
                UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                    [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [makeupalert addAction:OKAction];
                [makeupalert addAction:CancelAction];
                
                [MyClass presentViewController:makeupalert View:self];
            }else{
                [self cancelandtransfercourse];
            }
            
        }];
        
        UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
            [transferenrollmentalert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [transferenrollmentalert addAction:OKAction];
        [transferenrollmentalert addAction:CancelAction];
        
        //[self presentViewController:transferenrollmentalert animated:YES completion:nil];
        [MyClass presentViewController:transferenrollmentalert View:self];
    }
}


-(void) addpaymentforchangeenrollmentwithtransferamount:(float)transferamount
{
    [workingEnrollment.paymentrecords insertObject:[[PaymentRecord alloc]initPaymentRecordwithPaymentkey:@"" paymenttype:@"Class" paymenttypekey:PopoverEnrollment.enrollmentkey?PopoverEnrollment.enrollmentkey:@"" paiddate:[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"dd-MMM-yyyy"] paidmethod:@"Internal Transfer" paidamount:[NSString stringWithFormat:@"%g",transferamount] action:@"add" paymentremarks:@"Transfer course fee balance" receiptremarks:@"" staffname:[MyClass returnstaffnamewithusername:globalvariables.username firstorfullname:@"full"] receiptnumber:nil receiptprefix:nil] atIndex:0];
    
    //update enrollment popover data
    double totalpaid=0;
    
    for (int p=0; p<workingEnrollment.paymentrecords.count; p++) {
        DetailsPaymentObject=[workingEnrollment.paymentrecords objectAtIndex:p];
        totalpaid+=[DetailsPaymentObject.paidamount doubleValue];
    }
    
    workingEnrollment.paid=[NSString stringWithFormat:@"%g",totalpaid];
    [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];

}

