-(NSMutableArray *) returnduplicatedclasswithFreeScheduleArray:(NSMutableArray *)freeschedulearray
{
    duplicatedclassarray=[[NSMutableArray alloc]init];
    NSMutableArray *datetimearray=[[NSMutableArray alloc]init];
    NSString *datetime;
    FreeScheduleClass *freescheduleobject;
    
    
    for (int i=0; i<freeschedulearray.count; i++) {
        freescheduleobject=[freeschedulearray objectAtIndex:i];
        if (![freescheduleobject.action isEqualToString:@"Delete"] && ((![freescheduleobject.attendance isEqualToString:@"Makeup"] && ![freescheduleobject.classdate isEqualToString:@"TBD"] && ![freescheduleobject.classtime isEqualToString:@"TBD"]) || ([freescheduleobject.attendance isEqualToString:@"Makeup"] && ![freescheduleobject.makeupdate isEqualToString:@"TBD"] && ![freescheduleobject.makeuptime isEqualToString:@"TBD"] && ![freescheduleobject.makeupdate isEqualToString:@""] && ![freescheduleobject.makeuptime isEqualToString:@""]) )) {
            
            if ([freescheduleobject.attendance isEqualToString:@"Makeup"]) {
                datetime=[NSString stringWithFormat:@"%@ %@",freescheduleobject.makeupdate,freescheduleobject.makeuptime];
            }else{
                datetime=[NSString stringWithFormat:@"%@ %@",freescheduleobject.classdate,freescheduleobject.classtime];
            }
            
            if ([datetimearray containsObject:datetime]) {
                if(![duplicatedclassarray containsObject:datetime]){
                    [duplicatedclassarray addObject:[MyClass convertDateFormatWithDate:datetime FromDateFormat:@"dd-MMM-yyyy HH:mm" ToDateFormat:@"dd-MMM-yyyy HH:mm" Translate:YES]];
                }
            }else{
                [datetimearray addObject:datetime];
            }
        }
    }
    return duplicatedclassarray;
}

-(void) saveChangeSubjectFirstEnrollment
{
    NSString *tmpautorenew;
    NSString *tmpdropclassstatus;
    NSString *tmpdropclassdate;
    NSString *tmplatefee;
    NSString *tmplevelmain;
    NSString *tmplevelctm;
    NSString *tmpnoofclass;
    NSString *tmpclasstime;
    NSString *tmpstartdate;
    NSString *tmpenddate;
    NSString *tmpclassday;
    NSString *tmpinstructor;
    NSString *tmpsinstructor;
    NSString *tmpclassroom;
    
    if (![workingEnrollment.startdate isEqualToString:@"TBD"] && ![workingEnrollment.startdate isEqualToString:@""]) {
        tmpstartdate = workingEnrollment.startdate;
    }else{
        tmpstartdate=@"TBD";
        tmpclassday=@"TBD";
    }
    
    if (![workingEnrollment.enddate isEqualToString:@""]) {
        tmpenddate=workingEnrollment.enddate;
    }else{
        tmpenddate=@"TBD";
    }
    
    tmpclasstime=[workingEnrollment.classtime isEqualToString:@""]?@"TBD":workingEnrollment.classtime;
    tmpclassday=[workingEnrollment.classday isEqualToString:@""]?@"TBD":workingEnrollment.classday;
    tmpnoofclass=[workingEnrollment.noofclass isEqualToString:@""]?@"TBD":workingEnrollment.noofclass;
    tmpclassroom=[workingEnrollment.classroom isEqualToString:@""]?@"TBD":workingEnrollment.classroom;
    tmpautorenew=workingEnrollment.autorenew;
    tmpinstructor=[workingEnrollment.instructor isEqualToString:@""]?@"TBD":workingEnrollment.instructor;
    tmpsinstructor=[workingEnrollment.sinstructor isEqualToString:@""]?@"TBD":workingEnrollment.sinstructor;
    
    if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
            if ([tmpLevel isEqualToString:@""]) {
                tmplevelmain=@"TBD";
                tmplevelctm=@"";
            }else if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                tmplevelmain=tmpLevel;
                tmplevelctm=@"";
            }else{
                NSRange range=[tmpLevel rangeOfString:@"/"];
                if (range.location==NSNotFound) {
                    tmplevelmain=[tmpLevel substringFromIndex:3];
                    tmplevelctm=@"";
                }else{
                    tmplevelmain=[tmpLevel substringWithRange:NSMakeRange(3, range.location-3)];
                    tmplevelctm=[tmpLevel substringFromIndex:range.location+4];
                }
            }
    }else{
        if ([tmpLevel isEqualToString:@""]) {
            tmplevelmain=@"TBD";
        }else{
            tmplevelmain=tmpLevel;
        }
        tmplevelctm=@"";
    }
    
    tmpdropclassdate=workingEnrollment.dropclassdate;
    tmpdropclassstatus=workingEnrollment.dropclassstatus;
    tmplatefee=workingEnrollment.latefee;
    
    
    ChangeSubject_firstEnrollment=[[EnrollmentRecord alloc]initEnrollmentWithstudentkey:PopoverEnrollment.studentkey andenrollmentkey:PopoverEnrollment.enrollmentkey andenrollmentdate:workingEnrollment.enrollmentdate andschedulekey:workingEnrollment.schedulekey andsubject:workingEnrollment.subject andlevelmain:tmplevelmain andlevelctm:tmplevelctm andgrade:PopoverEnrollment.grade andstartdate:tmpstartdate andnoofclass:tmpnoofclass andenddate:tmpenddate andclassday:tmpclassday andclasstime:tmpclasstime andinstructor:tmpinstructor andenrollmentfee:workingEnrollment.enrollmentfee andtuitionfee:workingEnrollment.tuitionfee andoneoffdiscount:workingEnrollment.oneoffdiscount andrecursivediscount:@"" andoneoffpercentagediscount:workingEnrollment.oneoffpercentagediscount andlatefee:PopoverEnrollment.latefee andtotalfee:workingEnrollment.totalfee andpaid:workingEnrollment.paid anddropclassstatus:@"Yes" anddropclassdate:[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"dd-MMM-yyyy"] andremarks:workingEnrollment.remarks anddraft:@"" andinvoiceremarks:workingEnrollment.invoiceremarks andclassroom:tmpclassroom andautorenew:@"No" andstatus:PopoverEnrollment.status andreverseadjustment:PopoverEnrollment.reverseadjustment instructorfullname:nil subjectfullname:nil validity:workingEnrollment.validity makeup_quota:workingEnrollment.makeup_quota makeup_quota_used:@"" paymentrecords:nil promotiondiscountrecords:nil classrecords:nil sinstructor:tmpsinstructor transferredfromenrollmentkey:@"" enrollmentmode:PopoverEnrollment.enrollmentmode standardnoofclassormonth:PopoverEnrollment.standardnoofclassormonth couponrecords:nil invoicenumber:PopoverEnrollment.invoicenumber invoiceprefix:PopoverEnrollment.invoiceprefix locked:NO billdate:PopoverEnrollment.billdate resumeclassdate:@"" outstandingmakeupclasses:@""];
    
    ChangeSubject_FreeClassScheduleArray=[[NSMutableArray alloc]init];
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
        [ChangeSubject_FreeClassScheduleArray addObject:[[FreeScheduleClass alloc]initFreeScheduleClassWithclasskey:FreeScheduleClassObject.classkey subject:FreeScheduleClassObject.subject classdate:FreeScheduleClassObject.classdate classtime:FreeScheduleClassObject.classtime instructor:FreeScheduleClassObject.instructor classroom:FreeScheduleClassObject.classroom attendance:FreeScheduleClassObject.attendance makeupdate:FreeScheduleClassObject.makeupdate makeuptime:FreeScheduleClassObject.makeuptime makeupinstructor:FreeScheduleClassObject.makeupinstructor makeupclassroom:FreeScheduleClassObject.makeupclassroom makeupattendance:FreeScheduleClassObject.makeupattendance classremarks:FreeScheduleClassObject.classremarks allclassremarks:FreeScheduleClassObject.allclassremarks action:FreeScheduleClassObject.action  classtype:@"Class" leavenaturelistkey:FreeScheduleClassObject.leavenaturelistkey lesson:FreeScheduleClassObject.lesson sinstructor:FreeScheduleClassObject.sinstructor makeupsinstructor:FreeScheduleClassObject.makeupsinstructor locked:NO]];
    }
    
    ChangeSubject_DetailsPaymentArray=[[NSMutableArray alloc]init];
    for (int i=0; i<workingEnrollment.paymentrecords.count; i++) {
        DetailsPaymentObject=[workingEnrollment.paymentrecords objectAtIndex:i];
        [ChangeSubject_DetailsPaymentArray addObject:[[PaymentRecord alloc]initPaymentRecordwithPaymentkey:DetailsPaymentObject.paymentkey paymenttype:DetailsPaymentObject.paymenttype paymenttypekey:DetailsPaymentObject.paymenttypekey paiddate:DetailsPaymentObject.paiddate paidmethod:DetailsPaymentObject.paidmethod paidamount:DetailsPaymentObject.paidamount action:DetailsPaymentObject.action paymentremarks:DetailsPaymentObject.paymentremarks receiptremarks:DetailsPaymentObject.receiptremarks staffname:DetailsPaymentObject.staffname receiptnumber:nil receiptprefix:nil]];
    }
    
    ChangeSubject_UsedPromotionArray=[[NSMutableArray alloc]init];
    for (int i=0; i<workingEnrollment.promotiondiscountrecords.count; i++) {
        marketingobject=[workingEnrollment.promotiondiscountrecords objectAtIndex:i];
        [ChangeSubject_UsedPromotionArray addObject:marketingobject];
    }
}

