                    if (succeeded) {
                        result=TRUE;
                    }
                }];

                
            }else if ([TransferEnrollmentAction isEqualToString:@"Void"]){
                [self updateEnrollmentClassPaymentWithPopoverEnrollment:ChangeSubject_firstEnrollment FreeScheduleClassArray:ChangeSubject_FreeClassScheduleArray DetailsPaymentArray:ChangeSubject_DetailsPaymentArray draft:draft drafttovalid:NO Action:@"Edit" DTkey:nil PromotionArray:ChangeSubject_UsedPromotionArray updatelaterenrollmentslevel:updatelateenrollmentslevel CouponArray:ChangeSubject_UsedCouponArray];
                
                NSString *strURL=[NSString stringWithFormat:@"%@?centerdb=%@&centerkey=%@&action=voidenrollment&enrollmentkey=%@&reverseadjustment=%@&refund=%@&forfeit=%@&staffname=%@&studentkey=%@&refundmethod=%@&updatedby=%@&arckey=%@",globalvariables.generalphpfullpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey,PopoverEnrollment.enrollmentkey,ChangeSubject_firstEnrollment.totalfee,ChangeSubject_firstEnrollment.paid ,@"0",[MyClass returnstaffnamewithusername:globalvariables.username firstorfullname:@"full"],PopoverEnrollment.studentkey,@"Internal Transfer",globalvariables.username,[MyClass returndefaultarckey]];
                
                __block BOOL result=FALSE;
                [MyClass callGETwithURL:strURL completionBlock:^(BOOL succeeded, NSData *data) {
