                    }
                }];
        }
        TransferEnrollmentAction=nil;
            
            tmpenrollmentrecord=[[EnrollmentRecord alloc]initEnrollmentWithstudentkey:PopoverStudent.studentkey andenrollmentkey:@"" andenrollmentdate:workingEnrollment.enrollmentdate andschedulekey:workingEnrollment.schedulekey andsubject:workingEnrollment.subject andlevelmain:workingEnrollment.levelmain andlevelctm:workingEnrollment.levelctm andgrade:PopoverStudent.grade andstartdate:tmpstartdate andnoofclass:tmpnoofclass andenddate:tmpenddate andclassday:tmpclassday andclasstime:tmpclasstime andinstructor:tmpinstructor andenrollmentfee:workingEnrollment.enrollmentfee andtuitionfee:workingEnrollment.tuitionfee andoneoffdiscount:workingEnrollment.oneoffdiscount andrecursivediscount:@"" andoneoffpercentagediscount:workingEnrollment.oneoffpercentagediscount andlatefee:@"0" andtotalfee: workingEnrollment.totalfee andpaid:workingEnrollment.paid anddropclassstatus:@"No" anddropclassdate:@"" andremarks:workingEnrollment.remarks anddraft:draft andinvoiceremarks:workingEnrollment.invoiceremarks andclassroom:tmpclassroom andautorenew:tmpautorenew andstatus:@"" andreverseadjustment:@"" instructorfullname:nil subjectfullname:nil validity:workingEnrollment.validity makeup_quota:workingEnrollment.makeup_quota makeup_quota_used:@"" paymentrecords:workingEnrollment.paymentrecords promotiondiscountrecords:workingEnrollment.promotiondiscountrecords classrecords:nil sinstructor:tmpsinstructor transferredfromenrollmentkey:@"" enrollmentmode:workingEnrollment.enrollmentmode standardnoofclassormonth:workingEnrollment.standardnoofclassormonth couponrecords:workingEnrollment.couponrecords invoicenumber:nil invoiceprefix:nil locked:NO billdate:workingEnrollment.billdate resumeclassdate:workingEnrollment.resumeclassdate outstandingmakeupclasses:@""];
                
        result=[self updateEnrollmentClassPaymentWithPopoverEnrollment:tmpenrollmentrecord FreeScheduleClassArray:FreeScheduleClassArray DetailsPaymentArray:workingEnrollment.paymentrecords draft:draft drafttovalid:drafttovalid Action:@"Add" DTkey:dtkey PromotionArray:workingEnrollment.promotiondiscountrecords updatelaterenrollmentslevel:updatelateenrollmentslevel CouponArray:workingEnrollment.couponrecords];
        if (result) {
                // for transfer subject

            PopoverEnrollment=tmpenrollmentrecord;
        }else{
            [MyClass showconnectionlostdialogbox];
        }
    }
            
    if (result && !voidenrollment) {
        
        if ([PopoverStudent.status isEqualToString:@"Inactive"]) {
            PopoverStudent.status=@"No";
            
        }
        
        EnrollmentTableMode=@"View";
        
        PopoverEnrollment=[self.delegate refreshstudentdetailsinformationandreturnenrollementrecord:workingEnrollment];
        
