-(IBAction) cancelButtonPressed:(id)sender
{
    EnrollmentTableMode=@"View";
    if (![self InitializeFieldWithEnrollmentTableMode:EnrollmentTableMode]){
        return;
    }
    
    [self createViewBarButton];
    
    if (FreeScheduleClassArray.count>0) {
        noclassrecordlabel.hidden=YES;
    }
    
    if (showDLClassDateTable || showDLClassroomTable || showDLInstructorTable) {
        [self showsidewindowwithwindow:@"showDetailLesson"];
    }
    
    [EnrollmentPopoverTable reloadData];
    [self createDetailLessonToolBar];
    [self adjusttablesize];
    
}



