- (NSString *) calculateTuitionFeeWithClass:(NSString *)class Levelmain:(NSString *)levelmain noOfClass:(NSString *)noofclass startdatetime:(NSString *)startdatetime freescheduleclassarray:(NSMutableArray *)freescheduleclassarray{
    
    [self autoApplyPromotion];
    
    workingEnrollment.makeup_quota=[self calculateMakeupQuota];
    [self updatenewschedulewithfiltertimearray:NO];
    
    if(![self checklevelexistance]){
        levelmain=@"";
    }

    NSString *tuitionmode=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:class centerkey:globalvariables.centerrecord.centerkey]).tuition_mode;
    
    if ([levelmain isEqualToString:@""] || [noofclass isEqualToString:@""] || ([startdatetime isEqualToString:@""] && [tuitionmode isEqualToString:@"Month"])) {
        return @"0";
    }else{
        return [MyClass calculateTuitionFeeWithClass:class Levelmain:levelmain noOfClass:noofclass startdatetime:startdatetime schedulekey:workingEnrollment.schedulekey schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] Grade:((Student *)[MyClass returnstudentwithstudentkey:PopoverStudent.studentkey]).grade EnrollmentTableMode:nil freescheduleclassarray:freescheduleclassarray];
    }
}


- (void) calculateTotalFeeWithEnrollmentFee:(NSString *)enrollmentfee TuitionFee:(NSString *)tuitionfee LateFee:(NSString *)latefee{
    
    [self calculatetotaldiscount];
    
    float thetotalfee=0;
    NSString *result;
    
    thetotalfee=[tuitionfee floatValue]-[tmpTotalDiscount floatValue]+[enrollmentfee floatValue]+[latefee floatValue];
    
    if (noofroundoffdigit==1) {
        if (thetotalfee==(int)thetotalfee) {
            result=[NSString stringWithFormat:@"%g",thetotalfee];
        }else{
            if ([[NSString stringWithFormat:@"%.1f",thetotalfee] hasSuffix:@".0"]) {
                result= [[NSString stringWithFormat:@"%.1f",thetotalfee] substringToIndex:[[NSString stringWithFormat:@"%.1f",thetotalfee] length]-2];
            }else{
                result= [NSString stringWithFormat:@"%.1f",thetotalfee];
            }
        }
    }else{
        result=[NSString stringWithFormat:@"%ld",lroundf(thetotalfee)];
    }
    

    
    if (showDetailPayment) {
        paymenttotalfeeLabel.text=result;
        paymentoutstandingLabel.text=[NSString stringWithFormat:@"%g",[paymenttotalfeeLabel.text doubleValue]-[paymenttotalpaidLabel.text doubleValue]];
    }
    
    workingEnrollment.totalfee=result;
    
//    TotalFeeLabel.text=workingEnrollment.totalfee;
    [EnrollmentPopoverTable reloadData];
    //return result;
}

