            DetailsPaymentObject=[detailspaymentarray objectAtIndex:i];
            if ([DetailsPaymentObject.action isEqualToString:@"add"] || [DetailsPaymentObject.action isEqualToString:@"edit"]) {
                values=[NSArray arrayWithObjects:DetailsPaymentObject.paymentkey,DetailsPaymentObject.paymenttypekey,[MyClass convertDDMMMYYYYtoYYYYMMDDwithdate:DetailsPaymentObject.paiddate],DetailsPaymentObject.paidamount,DetailsPaymentObject.paidmethod,DetailsPaymentObject.paymenttype,DetailsPaymentObject.paymentremarks,DetailsPaymentObject.receiptremarks,DetailsPaymentObject.staffname, DetailsPaymentObject.action, [MyClass returndefaultarckey], nil];
                
                dict = [NSDictionary dictionaryWithObjects:values forKeys:keys];
                [arrayOfDicts addObject:dict];
            }
        }
        jsonpaymentarray = [NSArray arrayWithArray:arrayOfDicts];
    }
    
    //generate json promotion array
    if (promotionarray.count>0) {
        
        arrayOfDicts = [[NSMutableArray alloc] init];
        keys=[NSArray arrayWithObjects:@"marketingkey",@"recursive",nil];
        
        for (long i =0; i< promotionarray.count; i++) {
            //for (int i = 0; i<detailspaymentarray.count; i++) {
            marketingobject=[promotionarray objectAtIndex:i];
            
            values=[NSArray arrayWithObjects:marketingobject.marketingkey,marketingobject.recursive, nil];
            
            dict = [NSDictionary dictionaryWithObjects:values forKeys:keys];
            [arrayOfDicts addObject:dict];
        }
        jsonpromotionarray = [NSArray arrayWithArray:arrayOfDicts];
    }
    
    //generate json coupon array
    if (couponarray.count>0) {
        
        arrayOfDicts = [[NSMutableArray alloc] init];
        keys=[NSArray arrayWithObjects:@"couponkey",nil];
        
        for (long i =0; i< couponarray.count; i++) {
            //for (int i = 0; i<detailspaymentarray.count; i++) {
            CouponRecord *obj=[couponarray objectAtIndex:i];
            
            values=[NSArray arrayWithObjects:obj.couponkey,nil];
            
            dict = [NSDictionary dictionaryWithObjects:values forKeys:keys];
            [arrayOfDicts addObject:dict];
        }
        jsoncouponarray = [NSArray arrayWithArray:arrayOfDicts];
    }
    
    
    
    [dictionary setValue:globalvariables.username forKey:@"updatedby"];
    [dictionary setValue:jsonclassarray forKey:@"classarray"];
    [dictionary setValue:jsonpaymentarray forKey:@"paymentarray"];
    [dictionary setValue:jsonpromotionarray forKey:@"promotionarray"];
    [dictionary setValue:jsoncouponarray forKey:@"couponarray"];

    __block BOOL result=FALSE;
    __block BOOL reloadEnrollmentTable=FALSE;
    __block BOOL reloadSubject=FALSE;
    __block BOOL existingschedulefound=FALSE;
     
     
    [MyClass callPOSTwithDict:dictionary completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            NSDictionary *jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
            JSONArray=jsonreturned[@"content"];
            
            if ([[[JSONArray objectAtIndex:0] objectForKey:@"result"] isEqualToString:@"success"]) {
                popoverenrollment.enrollmentkey=[[JSONArray objectAtIndex:0] objectForKey:@"enrollmentkey"];
                workingEnrollment.enrollmentkey=popoverenrollment.enrollmentkey;
//                NSArray *paymentkeyarray=[[[JSONArray objectAtIndex:0] objectForKey:@"paymentkey"] componentsSeparatedByString:@","];
//                popoverenrollment.makeup_quota_used=[[JSONArray objectAtIndex:0] objectForKey:@"makeup_quota_used"];
//                workingEnrollment.makeup_quota_used=popoverenrollment.makeup_quota_used;

                
//                int newpaymentkeycount=0;
//                for (int p=0; p<detailspaymentarray.count; p++) {
//                    DetailsPaymentObject=[detailspaymentarray objectAtIndex:p];
//                    if ([DetailsPaymentObject.action isEqualToString:@"add"]) {
//                        DetailsPaymentObject.paymentkey=[paymentkeyarray objectAtIndex:newpaymentkeycount];
//                        DetailsPaymentObject.action=@"locked";
//                        if([DetailsPaymentObject.paidamount floatValue]>0 && ![DetailsPaymentObject.paymentremarks isEqualToString:@"Transfer course fee balance"]){
////                            newReceiptToBeMessaged=TRUE;
//                        }
//                        newpaymentkeycount +=1;
//
//                    }
//                }
                
                //update enrollment paid amount
                tmppaidamount=[[JSONArray objectAtIndex:0] objectForKey:@"enrollmentpaidamount"];
                //TotalPaidLabel.text=tmppaidamount;
                
                if (!TransferEnrollmentAction) {
                    workingEnrollment.paid=tmppaidamount;
                    popoverenrollment.paid=workingEnrollment.paid;
                    reloadEnrollmentTable=TRUE;
                

                    //refresh subject
                    if ([workingEnrollment.schedulekey isEqualToString:@"999999999"]) {
                        ScheduleTableMode=@"View";
                        
                        workingEnrollment.schedulekey=[[JSONArray objectAtIndex:0] objectForKey:@"schedulekey"];
                        popoverenrollment.schedulekey=workingEnrollment.schedulekey;
                        if ([[[JSONArray objectAtIndex:0] objectForKey:@"newschedulekey"] isEqualToString:@"No"]) {
                            existingschedulefound=TRUE;
                        }else{
                            reloadSubject=TRUE;
                        }
                        reloadEnrollmentTable=TRUE;
                        //[EnrollmentPopoverTable reloadData];
                        
                    }
                }
                
                result=TRUE;
            }
        }
    }];


    if (result) {
        //auto message receipt
        /*if(newReceiptToBeMessaged && globalvariables.centerrecord.autosendereceipt){
            [self autosendereceipt];
        }*/
        
        if (reloadEnrollmentTable) {
            [EnrollmentPopoverTable reloadData];
        }
        
        if(reloadSubject){
            subjectArray=[MyClass retrievesubjectinformationwithstatus:@"Active" category:@"All" flushcachedata:YES];
            filteredSubjectArray=[[NSMutableArray alloc]initWithArray:subjectArray];
            ScheduleArray=[[NSMutableArray alloc]initWithArray:((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).scheduleArray];
            filteredScheduleArray=[[NSMutableArray alloc]initWithArray:ScheduleArray];
        }
        
        if (existingschedulefound) {
            UIAlertController *successalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Course Schedule"] message:[NSString stringWithFormat:@"%@ (%@)",[MyClass returntitlewithtitle:@"Existing schedule found"],[MyClass returnschedulenamewithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey]] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                [successalert dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [successalert addAction:OKAction];
            //[self presentViewController:successalert animated:YES completion:nil];
            [MyClass presentViewController:successalert View:self];
        }
    }

    return result;
}



- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView
{
    // Return the number of sections.
    if (tableView==EnrollmentPopoverTable) {
        if ([EnrollmentTableMode isEqualToString:@"View"] || [EnrollmentTableMode isEqualToString:@"RenewalDrop"]) {
            return 6;
        }else if ([EnrollmentTableMode isEqualToString:@"Edit"]){
            return 6;
        }else{
            return 5;
        }
    }else if (tableView==DetailsPaymentTable) {
        if ([DetailsPaymentTableMode isEqualToString:@"View"]) {
            return 3;
        }else if ([DetailsPaymentTableMode isEqualToString:@"Add"]){
            if (workingEnrollment.paymentrecords.count==0) {
                return 2;
            }else{
                return 3;
            }
        }else if ([DetailsPaymentTableMode isEqualToString:@"Edit"]){
            return 1;
        }else{ //editinvoiceremarks
            return 1;
        }
    }else if (tableView==DiscountTable){
        return 4;
    }
    return 1;
}

- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section
{
    if (tableView==EnrollmentPopoverTable) {
        if ([EnrollmentTableMode isEqualToString:@"View"] || [EnrollmentTableMode isEqualToString:@"RenewalDrop"]) {
            if (section==0) {
                return 13;
            }else if (section==1){
                return 2;
            }else if (section==2){
                return 6;
            }else if (section==3){
                return 1;
            }else if (section==4){
                return 4;
            }else{
                return 1;
            }
        }else if ([EnrollmentTableMode isEqualToString:@"Add"]){
            if (section==0) {
                return 18;
            }else if (section==1){
                return 4;
            }else if (section==2){
                return 7;
            }else if (section==3){
                return 1;
            }else{// if (section==4){
                return 6;
            }
        }else{// if ([EnrollmentTableMode isEqualToString:@"Edit"] or renewal){
            if (section==0) {
                return 18;
            }else if (section==1){
                return 4;
            }else if (section==2){
                return 7;
            }else if (section==3){
                return 1;
            }else if (section==4){
                return [PopoverEnrollment.status isEqualToString:@"Voided"]||[self hasLockedClass]?4:6;
            }else{
                return 1;
            }
        }
    }else if (tableView==DetailsPaymentTable) {
        if ([DetailsPaymentTableMode isEqualToString:@"View"]) {
            if (section==0) {
                return 3;
            }else if (section==1){
                return workingEnrollment.paymentrecords.count;
            }else{
                return 1;
            }
        }else if ([DetailsPaymentTableMode isEqualToString:@"Add"]){
            if (workingEnrollment.paymentrecords.count==0) {
                if (section==0) {
                    return 3;
                }else{
                    return 8;
                }
            }else{
                if (section==0) {
                    return 3;
                }else if (section==1){
                    return 8;
                }else{
                    return workingEnrollment.paymentrecords.count;
                }
            }
        }else if ([DetailsPaymentTableMode isEqualToString:@"Edit"]){
            return 5;
        }else{
            return 1;
        }
    }else if (tableView==DetailLessonTable){
        return showDetailLesson?FreeScheduleClassArray.count:0;
    }else if (tableView==SubjectTable){
        return showSubjectTable?filteredSubjectArray.count:0;
    }else if (tableView==InstructorTable){
        return showInstructorTable?filteredAvailableInstructorArray.count:0;
    }else if (tableView==DiscountTable){
        if (section==0) {
            return workingEnrollment.promotiondiscountrecords.count;
        }else if (section==1){//
            return 2;
        }else if (section==2){//
            return globalvariables.centerrecord.ecoupon?workingEnrollment.couponrecords.count:0;
        }else{
            return 1;
        }
    }else if (tableView==PromotionCodeTable){
        return showpromotioncodetable?filteredavailablepromotionarray.count:0;
    }else if (tableView==CouponTable){
        return showcoupontable?filteredavailablecouponarray.count:0;
    }else if (tableView==VoidTable){
        return 7;
    }else if (tableView==ClassroomTable){
        return showClassroomTable?FilteredClassroomArray.count:0;
    }else if (tableView==ScheduleTable){
        if ([ScheduleTableMode isEqualToString:@"View"]) {
            return filteredScheduleArray.count;
        }else{
            return 11;
        }
    }else if (tableView==DLClassDateTable){
        return showDLClassDateTable?1:0;
    }else if (tableView==DLInstructorTable){
        return showDLInstructorTable?filteredAvailableInstructorArray.count:0;
    }else if (tableView==DLClassroomTable){
        return showDLClassroomTable?FilteredClassroomArray.count:0;
    }else if (tableView==csInstructorTable){
        return showcsInstructorTable?filteredcsInstructorArray.count:0;
    }else if (tableView==csClassroomTable){
        return showcsClassroomTable?filteredcsClassroomArray.count:0;
    }else if (tableView==csClassDateTable){
        return showcsClassDateTable?1:0;
    }else if (tableView==leaveNatureTable){
        return leaveNatureArray.count;
    }else if (tableView==csDayDateTimeTable){
        return 1;
    }else if (tableView==sharetable){ //sharetable
        return 5;
    }else if (tableView==LessonNumberTable){
        return globalvariables.centerrecord.lessonnumbermode==2?1:lessonArray.count;
    }
    return 1;
}

