-(BOOL) couponcanbeselected:(CouponRecord *)coupon
{
    BOOL alreadyhascannotbeusedconjunctionwithothers=FALSE;
    for(int i=0;i<workingEnrollment.couponrecords.count;i++){
        CouponRecord *obj=[workingEnrollment.couponrecords objectAtIndex:i];
        if(obj.cannotuseconjunctionwithothercoupons){
            alreadyhascannotbeusedconjunctionwithothers=TRUE;
            break;
        }
    }
    
    if(workingEnrollment.couponrecords.count>0){
        if(!coupon.cannotuseconjunctionwithothercoupons && !alreadyhascannotbeusedconjunctionwithothers){
            return YES;
        }
    }else{
        return YES;
    }
    
    return NO;
}

-(void) deletepaymentbuttonpressed:(UIButton *)sender
{
    [workingEnrollment.paymentrecords removeObjectAtIndex:sender.tag];
    //justDeletePayment=YES;
    
    //update enrollment tool bar to enable draft saving
    if (workingEnrollment.paymentrecords.count==0) {
        if ([EnrollmentTableMode isEqualToString:@"Add"]) {
            [self createAddBarButtonwithDraftOption:YES];
        }else{
            [self createEditBarButtonwithDraftOption:YES];
        }
    }
    
    [DetailsPaymentTable reloadData];
    [self createPaymentToolBarwithMode:@"View"];
    
    //update enrollment data
    int tmptotalpaid=0;
    for (int p=0; p<workingEnrollment.paymentrecords.count; p++) {
        DetailsPaymentObject=[workingEnrollment.paymentrecords objectAtIndex:p];
        tmptotalpaid+=[DetailsPaymentObject.paidamount intValue];
    }
    workingEnrollment.paid=[NSString stringWithFormat:@"%d",tmptotalpaid];
    [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    //TotalPaidLabel.text=workingEnrollment.paid;
    [EnrollmentPopoverTable reloadRowsAtIndexPaths:@[[NSIndexPath indexPathForRow:6 inSection:2]] withRowAnimation:UITableViewRowAnimationNone];
}

-(void) reversepaymentbuttonpressed:(UIButton *)sender
{
    PaymentRecord *obj=[workingEnrollment.paymentrecords objectAtIndex:sender.tag];
    
    tmpPaidDate=[MyClass convertToNSStringWithNSDate:[NSDate date] DateFormat:@"dd-MMM-yyyy"];
    tmppaidmethod=obj.paidmethod;
    tmppaidamount=[NSString stringWithFormat:@"%g",-[obj.paidamount doubleValue]];
    tmppaymentremarks=@"Reverse payment";
    tmpreceiptremarks=@"";
    
    [workingEnrollment.paymentrecords insertObject:[[PaymentRecord alloc]initPaymentRecordwithPaymentkey:@"" paymenttype:@"Class" paymenttypekey:PopoverEnrollment.enrollmentkey?PopoverEnrollment.enrollmentkey:@"" paiddate:tmpPaidDate paidmethod:tmppaidmethod paidamount:tmppaidamount action:@"add" paymentremarks:tmppaymentremarks receiptremarks:tmpreceiptremarks staffname:[MyClass returnstaffnamewithusername:globalvariables.username firstorfullname:@"full"] receiptnumber:nil receiptprefix:nil] atIndex:0];
    
    //update enrollment popover data
    double totalpaid=0;
    
    for (int p=0; p<workingEnrollment.paymentrecords.count; p++) {
        DetailsPaymentObject=[workingEnrollment.paymentrecords objectAtIndex:p];
        totalpaid+=[DetailsPaymentObject.paidamount doubleValue];
    }
    
    workingEnrollment.paid=[NSString stringWithFormat:@"%g",totalpaid];
    [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    //TotalPaidLabel.text=workingEnrollment.paid;
    [EnrollmentPopoverTable reloadRowsAtIndexPaths:@[[NSIndexPath indexPathForRow:6 inSection:2]] withRowAnimation:UITableViewRowAnimationNone];
    //[self storeTmpField];
    
    DetailsPaymentTableMode=@"View";
    showPaymentDatePicker=NO;
    [DetailsPaymentTable reloadData];
    
    //update enrollment tool bar to disable draft saving
    if (workingEnrollment.paymentrecords.count==1) {
        if ([EnrollmentTableMode isEqualToString:@"Add"]) {
            [self createAddBarButtonwithDraftOption:NO];
        }else{
            [self createEditBarButtonwithDraftOption:NO];
        }
    }
    
    [self createPaymentToolBarwithMode:@"View"];


    if (![EnrollmentTableMode isEqualToString:@"Add"] && ![EnrollmentTableMode isEqualToString:@"Renewal"]) {
        [EnrollmentPopoverTable reloadRowsAtIndexPaths:@[[NSIndexPath indexPathForRow:0 inSection:5]] withRowAnimation:UITableViewRowAnimationAutomatic];
    }
}

-(void) recursivebuttonpressed:(UIButton *)sender
{
    CGPoint point = [sender.superview convertPoint:CGPointZero toView:DiscountTable];
    NSIndexPath *indexPath =[DiscountTable indexPathForRowAtPoint:point];
    
    MarketingRecord *obj=[workingEnrollment.promotiondiscountrecords objectAtIndex:indexPath.row];
    if ([obj.recursive isEqualToString:@"Yes"]) {
        obj.recursive=@"No";
    }else{
        obj.recursive=@"Yes";
    }
    [DiscountTable reloadData];
}

-(void) switchonlinetrialschedule:(UISwitch *)sender
{
    workingSchedule.onlinetrialschedule=sender.on;
}

