{
    if (textField==detailspaymentText) {
        if ([globalvariables.centerrecord.defaulteditablepaymentamount isEqualToString:@"No"]) {
            if (paymentoverride) {
                return YES;
            }else{
                return NO;
            }
        }else{
            return YES;
        }
    }else{
        return YES;
    }
}

