-(NSString *) returntotalpaidwithindexpath:(NSIndexPath *)indexpath
{
    float totalpaid=0;
    for (long i=indexpath.row; i<workingEnrollment.paymentrecords.count; i++) {
        totalpaid+=[((PaymentRecord *)[workingEnrollment.paymentrecords objectAtIndex:i]).paidamount floatValue];
    }
    
    return [NSString stringWithFormat:@"%g",totalpaid];
}

