-(void) autoApplyPromotion
{
    MarketingRecord *sourceobject;
    MarketingRecord *destobject;
    MarketingRecord *promotionobject;
    
    if(!workingEnrollment.studentkey || !workingEnrollment.enrollmentkey|| [workingEnrollment.subject isEqualToString:@""]){
        return;
    }
    
    if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
            if ([tmpLevel isEqualToString:@""]) {
                workingEnrollment.levelmain=@"TBD";
            }else if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                workingEnrollment.levelmain=tmpLevel;
            }else{
                NSRange range=[tmpLevel rangeOfString:@"/"];
                if (range.location==NSNotFound) {
                    workingEnrollment.levelmain=[tmpLevel substringFromIndex:3];
                }else{
                    workingEnrollment.levelmain=[tmpLevel substringWithRange:NSMakeRange(3, range.location-3)];
                }
            }
    }else{
        if ([tmpLevel isEqualToString:@""]) {
            workingEnrollment.levelmain=@"TBD";
        }else{
            workingEnrollment.levelmain=tmpLevel;
        }
    }
    
    
    SubjectRecord *object=[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey];
    __block BOOL result=FALSE;
    __block NSDictionary *jsonreturned;
    NSDictionary *dictionary = @{@"postaction" : @"getautoapplypromotion",
                                 @"centerdb" : globalvariables.centerrecord.centerdb,
                                 @"centerkey" : globalvariables.centerrecord.centerkey,
                                 @"enrollmentkey" : workingEnrollment.enrollmentkey,
                                 @"studentkey" : workingEnrollment.studentkey,
                                 @"enrollmentdate" : [MyClass convertDateFormatWithDate:workingEnrollment.enrollmentdate FromDateFormat:@"dd-MMM-yyyy" ToDateFormat:@"yyyy-MM-dd" Translate:NO],
                                 @"startdate" : [MyClass convertDateFormatWithDate:workingEnrollment.startdate FromDateFormat:@"dd-MMM-yyyy" ToDateFormat:@"yyyy-MM-dd" Translate:NO],
                                 @"enddate" : [MyClass convertDateFormatWithDate:workingEnrollment.enddate FromDateFormat:@"dd-MMM-yyyy" ToDateFormat:@"yyyy-MM-dd" Translate:NO],
                                 @"subjectkey" : object.subjectkey,
                                 @"levelmain" : workingEnrollment.levelmain,
                                 @"billdate" : [MyClass convertDateFormatWithDate:workingEnrollment.billdate FromDateFormat:@"dd-MMM-yyyy" ToDateFormat:@"yyyy-MM-dd" Translate:NO],
                                 @"noofclass" : workingEnrollment.noofclass,
                                 @"totalfee" : workingEnrollment.totalfee?workingEnrollment.totalfee:@""};
    
    [MyClass callPOSTwithDict:dictionary completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            result=TRUE;
            jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
        }
    }];
    
    if(result){
        NSDictionary * contentdict = jsonreturned[@"content"];
        NSArray * promotionrecords = contentdict[@"promotionrecords"];
        SubjectRecord *subjectobj=[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey];
        NSString *btspromotioncode831=subjectobj.btspromotioncode831;
        NSString *btspromotioncode1031=subjectobj.btspromotioncode1031;
        
        // 1. Build an index lookup dictionary from the initial state
        NSMutableDictionary<NSString *, NSNumber *> *orderMap = [NSMutableDictionary dictionary];
        [workingEnrollment.promotiondiscountrecords enumerateObjectsUsingBlock:^(id obj, NSUInteger idx, BOOL *stop) {
            NSString *key = [obj valueForKey:@"marketingkey"];
            if (key) {
                orderMap[key] = @(idx);
            }
        }];
        
        //remove all early bird andbuymorepayless promotions
        for (int p=0; p<workingEnrollment.promotiondiscountrecords.count; p++) {
            promotionobject=workingEnrollment.promotiondiscountrecords[p];
            if ([promotionobject.earlybirdlastdate isEqualToString:@"newearlybirddiscount"] || promotionobject.buymorepayless) {
                [workingEnrollment.promotiondiscountrecords removeObjectAtIndex:p];
                p--;
            }
        }
        
        
        for (int i=0; i<promotionrecords.count; i++) {
            NSString * marketingkey=[[promotionrecords objectAtIndex:i] objectForKey:@"marketingkey"];
            
            sourceobject=[MyClass returnmarketinginformationwithmarketingkey:marketingkey centerkey:globalvariables.centerrecord.centerkey];
            destobject=[[MarketingRecord alloc]initMarketingRecordWithcenterkey:sourceobject.centerkey marketingkey:sourceobject.marketingkey category:sourceobject.category description:sourceobject.description description_chinese:sourceobject.description_chinese startdate:sourceobject.startdate enddate:sourceobject.enddate remarks:sourceobject.remarks promotionfixeddiscount:sourceobject.promotionfixeddiscount promotionpercentagediscount:sourceobject.promotionpercentagediscount usedcount:sourceobject.usedcount promotionquota:sourceobject.promotionquota code:sourceobject.code recursive:sourceobject.recursive effectivefrom:nil effectiveto:nil subcategory:nil redeemable:NO redeempoint:nil perstudentquota:nil cannotuseconjunctionwithothercoupons:NO subjectarray:nil productarray:nil couponallowcredit:nil perclassorquantity:sourceobject.perclassorquantity earlybirdlastdate:@"newearlybirddiscount" buymorepayless:sourceobject.buymorepayless estartdate:nil eenddate:nil enablebuymorepayless:NO minnoofclass:0 bmsmacrossothersubjects:NO bmsmminsubjectno:0 bmsmminnoofclasspersubject:0 bmsmsamebillmonth:NO manualapply:sourceobject.manualapply];
            
            
            if ([sourceobject.code isEqualToString:btspromotioncode831] && ![btspromotioncode831 isEqualToString:@""]) {
                if (![self promotionContainsMaketingCode:sourceobject.code]) {
                    [workingEnrollment.promotiondiscountrecords addObject:destobject];
                }
            }else if ([sourceobject.code isEqualToString:btspromotioncode1031] && ![btspromotioncode1031 isEqualToString:@""]) {
                if (![self promotionContainsMaketingCode:sourceobject.code]) {
                    [workingEnrollment.promotiondiscountrecords addObject:destobject];
                }
            }else{
                [workingEnrollment.promotiondiscountrecords addObject:destobject];
            }
        }
        
        // 2. Sort newpromotionarray using block comparator
        [workingEnrollment.promotiondiscountrecords sortUsingComparator:^NSComparisonResult(id obj1, id obj2) {
            NSString *key1 = [obj1 valueForKey:@"marketingkey"];
            NSString *key2 = [obj2 valueForKey:@"marketingkey"];
            
            NSNumber *index1 = orderMap[key1];
            NSNumber *index2 = orderMap[key2];
            
            NSInteger pos1 = index1 ? index1.integerValue : NSIntegerMax;
            NSInteger pos2 = index2 ? index2.integerValue : NSIntegerMax;
            
            if (pos1 < pos2) return NSOrderedAscending;
            if (pos1 > pos2) return NSOrderedDescending;
            return NSOrderedSame;
        }];
        
        if (showDiscountTable) {
            [DiscountTable reloadData];
        }
    }
}

-(BOOL) promotionContainsMaketingCode:(NSString *)code
{
    MarketingRecord *obj;
    for (int i=0; i<workingEnrollment.promotiondiscountrecords.count; i++) {
        obj=[workingEnrollment.promotiondiscountrecords objectAtIndex:i];
        if ([obj.code isEqualToString:code]) {
            return YES;
        }
    }
    return FALSE;
}

