- (void)tableView:(UITableView *)tableView commitEditingStyle:(UITableViewCellEditingStyle)editingStyle forRowAtIndexPath:(NSIndexPath *)indexPath {
    
    if (tableView==DetailsPaymentTable) {
        if (editingStyle == UITableViewCellEditingStyleDelete) {
            //add code here for when you hit delete
            
            [workingEnrollment.paymentrecords removeObjectAtIndex:indexPath.row];
            //justDeletePayment=YES;
            
            //update enrollment tool bar to enable draft saving
            if (workingEnrollment.paymentrecords.count==0) {
                if ([EnrollmentTableMode isEqualToString:@"Add"]) {
                    [self createAddBarButtonwithDraftOption:YES];
                }else{
                    [self createEditBarButtonwithDraftOption:YES];
                }
            }
            
            [DetailsPaymentTable reloadData];
            [self createPaymentToolBarwithMode:@"View"];

            //update enrollment data
            int tmptotalpaid=0;
            for (int p=0; p<workingEnrollment.paymentrecords.count; p++) {
                DetailsPaymentObject=[workingEnrollment.paymentrecords objectAtIndex:p];
                tmptotalpaid+=[DetailsPaymentObject.paidamount intValue];
            }
            workingEnrollment.paid=[NSString stringWithFormat:@"%d",tmptotalpaid];
            [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
            //TotalPaidLabel.text=workingEnrollment.paid;
            [EnrollmentPopoverTable reloadRowsAtIndexPaths:@[[NSIndexPath indexPathForRow:6 inSection:2]] withRowAnimation:UITableViewRowAnimationNone];
        }
    }else if (tableView==DetailLessonTable){
        if (editingStyle == UITableViewCellEditingStyleDelete) {
            if ([((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).action isEqualToString:@"Add"]) {
                [FreeScheduleClassArray removeObjectAtIndex:indexPath.row];
            }else{
                //check if has extended class
                if ([((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).attendance isEqualToString:@"Extend"]) {
                    //NSMutableDictionary *dict=[MyClass classhasextendedclasswithclasskey:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).classkey enrollmentkey:nil];
                    if ([self hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).classkey FreeScheduleClassarray:FreeScheduleClassArray]) {
                        UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Cannot Delete Class"] message:[MyClass returntitlewithtitle:@"This class time has been used to extend other class"] preferredStyle:UIAlertControllerStyleAlert];
                        
                        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                            [missinginput dismissViewControllerAnimated:YES completion:nil];
                            return;
                        }];
                        
                        [missinginput addAction:OKAction];
                        //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
                    }else{
                        ((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).action=@"Delete";
                    }
                }else{
                     ((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:indexPath.row]).action=@"Delete";
                }
            }
            

            
            [DetailLessonTable reloadData];
            workingEnrollment.noofclass=[NSString stringWithFormat:@"%d",[MyClass returnnoofclasswithfreescheduleclassarray:FreeScheduleClassArray]];

            if ([workingEnrollment.noofclass isEqualToString:@"0"]) {
                workingEnrollment.noofclass=@"";
                workingEnrollment.classtime=@"";
                ///showDatePicker=NO;
                showTimePicker=NO;
                showNoOfClassPicker=NO;
                showEndMonthPicker=NO;
                
                workingEnrollment.startdate=@"";
                workingEnrollment.enddate=@"";
                tmpStartDateTime=@"";
                workingEnrollment.validity=@"";
                
                
            }else{
                tmpStartDateTime=[NSString stringWithFormat:@"%@ %@",((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classdate,((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classtime];
            }
            
            workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:tmpLevel noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
            [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
            [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
            //[self storeTmpField];
            [EnrollmentPopoverTable reloadData];
            
            if (showDLClassDateTable || showDLInstructorTable || showDLClassroomTable) {
                [self showsidewindowwithwindow:@"showDetailLesson"];
            }
            [self adjusttablesize];
        }
    }else if (tableView==DiscountTable){
        if (editingStyle == UITableViewCellEditingStyleDelete) {
            if(indexPath.section==0){
                [workingEnrollment.promotiondiscountrecords removeObjectAtIndex:indexPath.row];
                
                [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
                [DiscountTable reloadData];
            }else if(indexPath.section==2){
                CouponRecord *obj=[workingEnrollment.couponrecords objectAtIndex:indexPath.row];
                [workingEnrollment.couponrecords removeObjectAtIndex:indexPath.row];
                [availablecouponarray addObject:obj];
                [self returnFilteredCouponArray];

                
                [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
                [DiscountTable reloadData];
                if(showcoupontable){
                    [CouponTable reloadData];
                }
            }
        }
    }
}

-(void) validateDiscountUponEnrollmentDateChange
{
    BOOL updatetuition=FALSE;
    for (int i=0; i<workingEnrollment.promotiondiscountrecords.count; i++) {
        marketingobject=[workingEnrollment.promotiondiscountrecords objectAtIndex:i];
        if ([[MyClass convertToNSDateWithDate:workingEnrollment.enrollmentdate DateFormat:@"dd-MMM-yyyy"] compare:[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",marketingobject.enddate] DateFormat:@"dd-MMM-yyyy HH:mm:ss"]]==NSOrderedDescending){
            [workingEnrollment.promotiondiscountrecords removeObjectAtIndex:i];
            i-=1;
            updatetuition=TRUE;
        }
    }
    
    [self autoApplyPromotion];
    
    if (updatetuition) {
        [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
        [DiscountTable reloadData];
    }
}

- (BOOL)tableView:(UITableView *)tableView canEditRowAtIndexPath:(NSIndexPath *)indexPath {
    // Return YES if you want the specified item to be editable.
    
    if (tableView==DetailLessonTable){
        if (![DetailLessonMode isEqualToString:@"View"] && ![PopoverEnrollment.status isEqualToString:@"Voided"] && ![self hasLockedClass] &&![self isExpiredPromotion] && [self editPaidEnrollment]) {
            return disableclassdelete?NO:YES;
        }
    }else if (tableView==DiscountTable){
        if (indexPath.section==0) {
            return ([DiscountTableMode isEqualToString:@"View"] || [PopoverEnrollment.status isEqualToString:@"Voided"] || [self hasLockedClass] || !((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscount || (!((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscountifpaid && [PopoverEnrollment.paid floatValue]!=0 && ![EnrollmentTableMode isEqualToString:@"Renewal"]))?NO:YES;
        }else if (indexPath.section==2) {
            return ([DiscountTableMode isEqualToString:@"View"] || [PopoverEnrollment.status isEqualToString:@"Voided"] || [self hasLockedClass])?NO:YES;
        }
    }
    return NO;
}

