- (UIView *)tableView:(UITableView *)tableView viewForHeaderInSection:(NSInteger)section
{
    if (tableView==DiscountTable) {
        if (section==0) {
            if (availablepromotionarray.count>0) {
                UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 44)];
                header.backgroundColor=[UIColor systemGroupedBackgroundColor];
                
                UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(15, 14, 200, 32)];
                label.text=[[MyClass returntitlewithtitle:@"Promotion Discount"] uppercaseString];
                label.font=[UIFont systemFontOfSize:13];
                label.textColor=[UIColor grayColor];
                [header addSubview:label];
                
                UIButton *showpromotioncodebutton=[[UIButton alloc]initWithFrame:CGRectMake(tableView.frame.size.width-28,22, 28, 20)];
                [showpromotioncodebutton setImageEdgeInsets:UIEdgeInsetsMake(2.5, 6.5, 2.5, 6.5)];
                [showpromotioncodebutton setImage:[UIImage imageNamed:@"addphonebutton.png"] forState:UIControlStateNormal];
                [showpromotioncodebutton addTarget:self action:@selector(showpromotioncode:) forControlEvents:UIControlEventTouchUpInside];
                [header addSubview:showpromotioncodebutton];
                showpromotioncodebutton.hidden=[DiscountTableMode isEqualToString:@"View"] || !((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscount || [self hasLockedClass] || [PopoverEnrollment.status isEqualToString:@"Voided"]|| (!((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscountifpaid && [PopoverEnrollment.paid floatValue]!=0&& ![EnrollmentTableMode isEqualToString:@"Renewal"]);
                return header;
            }
        }else if (section==2) {
            if (availablecouponarray.count>0 && globalvariables.centerrecord.ecoupon) {
                UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 44)];
                header.backgroundColor=[UIColor systemGroupedBackgroundColor];
                
                UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(15, 14, 200, 32)];
                label.text=[[MyClass returntitlewithtitle:@"Coupon"] uppercaseString];
                label.font=[UIFont systemFontOfSize:13];
                label.textColor=[UIColor grayColor];
                [header addSubview:label];
                
                UIButton *showpromotioncodebutton=[[UIButton alloc]initWithFrame:CGRectMake(tableView.frame.size.width-28,22, 28, 20)];
                [showpromotioncodebutton setImageEdgeInsets:UIEdgeInsetsMake(2.5, 6.5, 2.5, 6.5)];
                [showpromotioncodebutton setImage:[UIImage imageNamed:@"addphonebutton.png"] forState:UIControlStateNormal];
                [showpromotioncodebutton addTarget:self action:@selector(showavailablecoupon:) forControlEvents:UIControlEventTouchUpInside];
                [header addSubview:showpromotioncodebutton];
                showpromotioncodebutton.hidden=[DiscountTableMode isEqualToString:@"View"]|| !((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).applycoupon || [self hasLockedClass] || [PopoverEnrollment.status isEqualToString:@"Voided"];
                return header;
            }
        }
    }else if (tableView==DetailLessonTable){
        UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 44)];
        header.backgroundColor=[UIColor systemGroupedBackgroundColor];
        
        UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(15, 14, 200, 32)];
        label.text=[[MyClass returntitlewithtitle:@"Class Records"] uppercaseString];
        label.font=[UIFont systemFontOfSize:13];
        label.textColor=[UIColor grayColor];
        [header addSubview:label];
        
        [changeStartingLessonButton setFrame:CGRectMake(0,14, tableView.frame.size.width-40, 28)];
        [changeStartingLessonButton setTitle:[MyClass returntitlewithtitle:@"Change Starting Lesson"] forState:UIControlStateNormal];
        changeStartingLessonButton.contentHorizontalAlignment=UIControlContentHorizontalAlignmentRight;
        [changeStartingLessonButton setTitleColor:[UIColor colorWithRed:0.0 green:122.0/255.0 blue:1.0 alpha:1.0] forState:UIControlStateNormal];
        [changeStartingLessonButton.titleLabel setFont:[UIFont boldSystemFontOfSize:14]];
        [changeStartingLessonButton addTarget:self action:@selector(changeStartingLessonButtonPressed) forControlEvents:UIControlEventTouchUpInside];
        //changeStartingLessonButton.hidden=YES;
        changeStartingLessonButton.hidden=[self hideChangeStartingLessonButton];
        [header addSubview:changeStartingLessonButton];
        return header;
    }
    
    NSString *headerTitle = [self tableView:tableView titleForHeaderInSection:section];
    
    if (headerTitle) {
        UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 44)];
        header.backgroundColor=[UIColor systemGroupedBackgroundColor];
        
        UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(15, 14, 200, 32)];
        label.text=[[MyClass returntitlewithtitle:headerTitle] uppercaseString];;
        label.font=[UIFont systemFontOfSize:13];
        label.textColor=[UIColor grayColor];
        [header addSubview:label];
        return header;
    }

    
    return nil;
}



