-(void) deleteEnrollment
{
    [MyClass loadingindicatorwithoption:@"start" color:@"lightgray"];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.1 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        //delete sql class and enrollment records
        NSString *strURL=[NSString stringWithFormat:@"%@?centerdb=%@&centerkey=%@&action=deleteenrollment&enrollmentkey=%@&updatedby=%@",globalvariables.generalphpfullpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey,PopoverEnrollment.enrollmentkey,globalvariables.username];
        __block BOOL result=FALSE;
        [MyClass callGETwithURL:strURL completionBlock:^(BOOL succeeded, NSData *data) {
            if (succeeded) {
                result=TRUE;
            }
        }];
        
        /*
        dispatch_semaphore_t semaphore = dispatch_semaphore_create(0);
        NSURLSession *session = [NSURLSession sharedSession];
        [[session dataTaskWithURL:[NSURL URLWithString:[strURL stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLQueryAllowedCharacterSet]]] completionHandler:^(NSData *data, NSURLResponse *response, NSError *error) {

            dispatch_semaphore_signal(semaphore);
        }] resume];
        dispatch_semaphore_wait(semaphore, DISPATCH_TIME_FOREVER);*/
        
        [self.delegate dismissEnrollmentPopoverandResetFilter:NO];
        [MyClass loadingindicatorwithoption:@"stop" color:nil];
    });
}


- (void) updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray
{
    if (FreeScheduleClassArray.count==0) {
        workingEnrollment.startdate=@"";
        workingEnrollment.classtime=@"";
        workingEnrollment.enddate=@"";
        tmpStartDateTime=@"";
        workingEnrollment.classday=@"";
        workingEnrollment.validity=@"";
    }else{
        NSString *startdatestring=@"";
        NSString *enddatestring=@"";
        NSString *classdaystring=@"";
        NSString *instructorstring=@"";
        NSString *sinstructorstring=@"";
        NSString *classroomstring=@"";
        NSString *classtimestring=@"";
        
        FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
        for (long i=0; i<FreeScheduleClassArray.count;i++) {
            freescheduleclassobject=[FreeScheduleClassArray objectAtIndex:i];
            
            if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
                if ([startdatestring isEqualToString:@""]) {
                    startdatestring=freescheduleclassobject.classdate;
                    enddatestring=freescheduleclassobject.classdate;
                    classdaystring=[MyClass returndayofweek:enddatestring];
                    instructorstring=freescheduleclassobject.instructor;
                    sinstructorstring=freescheduleclassobject.sinstructor;
                    classtimestring=freescheduleclassobject.classtime;
                    classroomstring=freescheduleclassobject.classroom;
                }else{
                    
                    //determine startdate
                    if ([freescheduleclassobject.classdate isEqualToString:@"TBD"]) {
                        //if (![enddatestring isEqualToString:@"TBD"] && ![enddatestring isEqualToString:@"TBF"]) {
                        //    enddatestring=@"TBF";
                        //}
                    }else if (![freescheduleclassobject.classdate isEqualToString:@"TBD"]){// && ![freescheduleclassobject.classdate isEqualToString:@"TBF"]) {
                        if ([startdatestring isEqualToString:@"TBD"]){
                            startdatestring=freescheduleclassobject.classdate;
                        }else if (![startdatestring isEqualToString:@"TBF"]) {
                            //find end date
                            [df setDateFormat:@"dd-MMM-yyyy"];
                            if ([[df dateFromString:startdatestring] compare:[df dateFromString:freescheduleclassobject.classdate]]==NSOrderedDescending) {
                                startdatestring=freescheduleclassobject.classdate;
                            }
                        }
                        
                    }
                    
                    //determine enddatestring
                    if ([freescheduleclassobject.classdate isEqualToString:@"TBD"]) {
                        if (![enddatestring isEqualToString:@"TBD"] && ![enddatestring isEqualToString:@"TBF"]) {
                            enddatestring=@"TBF";
                        }
                    }else if (![freescheduleclassobject.classdate isEqualToString:@"TBD"] && ![freescheduleclassobject.classdate isEqualToString:@"TBF"]) {
                        if ([enddatestring isEqualToString:@"TBD"]){
                            enddatestring=@"TBF";
                        }else if (![enddatestring isEqualToString:@"TBF"]) {
                            //find end date
                            [df setDateFormat:@"dd-MMM-yyyy"];
                            if ([[df dateFromString:enddatestring] compare:[df dateFromString:freescheduleclassobject.classdate]]==NSOrderedAscending) {
                                enddatestring=freescheduleclassobject.classdate;
                            }
                        }
                        
                    }
                    
                    //determine classdaystring
                    if (![classdaystring isEqualToString:@"TBF"]) {
                        if ([[MyClass returndayofweek:freescheduleclassobject.classdate] isEqualToString:@"TBD"]) {
                            if (![classdaystring isEqualToString:@"TBD"]) {
                                classdaystring=@"TBF";
                            }
                        }else{
                            if ([classdaystring isEqualToString:@"TBD"]) {
                                classdaystring=@"TBF";
                            }else if (![classdaystring isEqualToString:@"Multi"]){
                                if (![classdaystring isEqualToString:[MyClass returndayofweek:freescheduleclassobject.classdate]]) {
                                    classdaystring=@"Multi";
                                }
                            }
                        }
                    }
                    
                    //determine instructorstring
                    if (![instructorstring isEqualToString:@"TBF"]) {
                        if ([freescheduleclassobject.instructor isEqualToString:@"TBD"]) {
                            if (![instructorstring isEqualToString:@"TBD"]) {
                                instructorstring=@"TBF";
                            }
                        }else{
                            if ([instructorstring isEqualToString:@"TBD"]) {
                                instructorstring=@"TBF";
                            }else if (![instructorstring isEqualToString:@"Multi"]){
                                if (![instructorstring isEqualToString:freescheduleclassobject.instructor]) {
                                    instructorstring=@"Multi";
                                }
                            }
                        }
                    }
                    
                    //determine sinstructorstring
                    if (![sinstructorstring isEqualToString:@"TBF"]) {
                        if ([freescheduleclassobject.sinstructor isEqualToString:@"TBD"]) {
                            if (![sinstructorstring isEqualToString:@"TBD"]) {
                                sinstructorstring=@"TBF";
                            }
                        }else{
                            if ([sinstructorstring isEqualToString:@"TBD"]) {
                                sinstructorstring=@"TBF";
                            }else if (![sinstructorstring isEqualToString:@"Multi"]){
                                if (![sinstructorstring isEqualToString:freescheduleclassobject.sinstructor]) {
                                    sinstructorstring=@"Multi";
                                }
                            }
                        }
                    }
                    
                    //determine classroomstring
                    if (![classroomstring isEqualToString:@"TBF"]) {
                        if ([freescheduleclassobject.classroom isEqualToString:@"TBD"]) {
                            if (![classroomstring isEqualToString:@"TBD"]) {
                                classroomstring=@"TBF";
                            }
                        }else{
                            if ([classroomstring isEqualToString:@"TBD"]) {
                                classroomstring=@"TBF";
                            }else if (![classroomstring isEqualToString:@"Multi"]){
                                if (![classroomstring isEqualToString:freescheduleclassobject.classroom]) {
                                    classroomstring=@"Multi";
                                }
                            }
                        }
                    }
                    
                    
                    //determine classtimestring
                    if (![classtimestring isEqualToString:@"TBF"]) {
                        if ([freescheduleclassobject.classtime isEqualToString:@"TBD"]) {
                            if (![classtimestring isEqualToString:@"TBD"]) {
                                classtimestring=@"TBF";
                            }
                        }else{
                            if ([classtimestring isEqualToString:@"TBD"]) {
                                classtimestring=@"TBF";
                            }else if (![classtimestring isEqualToString:@"Multi"]){
                                if (![classtimestring isEqualToString:freescheduleclassobject.classtime]) {
                                    classtimestring=@"Multi";
                                }
                            }
                        }
                    }
                }
            }
        }
        
        if ([workingEnrollment.startdate isEqualToString:@""]) {
            if (![startdatestring isEqualToString:@"TBD"]) {
                workingEnrollment.startdate=startdatestring;
                //StartDateLabel.text=startdatestring;
            }
        }else{
            if (![startdatestring isEqualToString:@""]) {
                workingEnrollment.startdate=startdatestring;
                //StartDateLabel.text=startdatestring;
            }
        }
        
        if ([workingEnrollment.enddate isEqualToString:@""]) {
            if (![enddatestring isEqualToString:@"TBD"]) {
                workingEnrollment.enddate=enddatestring;
                //EndDateLabel.text=enddatestring;
            }
        }else{
            if (![enddatestring isEqualToString:@""]) {
                workingEnrollment.enddate=enddatestring;
                //EndDateLabel.text=enddatestring;
            }
        }
        
        
        
        
        if (FreeScheduleClassArray.count==0 && ![workingEnrollment.startdate isEqualToString:@""] && ![workingEnrollment.startdate isEqualToString:@"TBD"]) {
            workingEnrollment.classday=[MyClass returndayofweek:workingEnrollment.startdate];
        }else{
            if ([workingEnrollment.startdate isEqualToString:@""]) {
                workingEnrollment.classday=@"";
                //ClassDayLabel.text=@"";
            }else{
                workingEnrollment.classday=classdaystring;
                //ClassDayLabel.text=classdaystring;
            }
        }
        
        if ([workingEnrollment.instructor isEqualToString:@""]) {
            if (![instructorstring isEqualToString:@"TBD"]) {
                //workingEnrollment.instructor=[MyClass returninstructornamewithusername:instructorstring firstorfullname:@"full"];
                workingEnrollment.instructor=instructorstring;
            }
        }else{
            if (![instructorstring isEqualToString:@""]) {
                //workingEnrollment.instructor=[MyClass returninstructornamewithusername:instructorstring firstorfullname:@"full"];
                workingEnrollment.instructor=instructorstring;
            }
        }
        
        if ([workingEnrollment.sinstructor isEqualToString:@""]) {
            if (![sinstructorstring isEqualToString:@"TBD"]) {
                //workingEnrollment.instructor=[MyClass returninstructornamewithusername:instructorstring firstorfullname:@"full"];
                workingEnrollment.sinstructor=sinstructorstring;
            }
        }else{
            if (![sinstructorstring isEqualToString:@""]) {
                //workingEnrollment.instructor=[MyClass returninstructornamewithusername:instructorstring firstorfullname:@"full"];
                workingEnrollment.sinstructor=sinstructorstring;
            }
        }
        
        if ([workingEnrollment.classroom isEqualToString:@""]) {
            if (![classroomstring isEqualToString:@"TBD"]) {
                workingEnrollment.classroom=classroomstring;
            }
        }else{
            if (![classroomstring isEqualToString:@""]) {
                workingEnrollment.classroom=classroomstring;
            }
        }
        
        
        if ([workingEnrollment.classtime isEqualToString:@""]) {
            if (![classtimestring isEqualToString:@"TBD"]) {
                workingEnrollment.classtime=classtimestring;
            }
        }else{
            if (![classtimestring isEqualToString:@""]) {
                workingEnrollment.classtime=classtimestring;
            }
            
        }
        
        if ([workingEnrollment.schedulekey intValue]<0) {
            tmpStartDateTime=workingEnrollment.startdate;
        }else{
            //tmpStartDateTime=[NSString stringWithFormat:@"%@ %@",workingEnrollment.startdate,workingEnrollment.classtime];
            tmpStartDateTime=[NSString stringWithFormat:@"%@ %@",((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classdate,((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classtime];
        }
        workingEnrollment.validity=[self returnvalidityvalue];
        
    }
    
    changeStartingLessonButton.hidden=[self hideChangeStartingLessonButton];
}

-(BOOL) hideChangeStartingLessonButton
{
    return ![self showLessonParameter] || [EnrollmentTableMode isEqualToString:@"View"] || [PopoverEnrollment.status isEqualToString:@"Voided"] || [self returnFreeScheduleClassArrayNonDeletedRowCount]==0;
}

-(NSInteger) returnFreeScheduleClassArrayNonDeletedRowCount
{

    NSInteger result=0;
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        if (![((FreeScheduleClass *)[FreeScheduleClassArray objectAtIndex:i]).action isEqualToString:@"Delete"]) {
            result++;
        }
    }
    return result;
}


-(void) resetFreeScheduleClassArraywithFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    for (int i=0; i<freescheduleclassarray.count; i++) {
        FreeScheduleClassObject=[freescheduleclassarray objectAtIndex:i];
        if ([FreeScheduleClassObject.action isEqualToString:@"Add"]) {
            [freescheduleclassarray removeObjectAtIndex:i];
            i-=1;
        }else if ([FreeScheduleClassObject.action isEqualToString:@""] || [FreeScheduleClassObject.action isEqualToString:@"Edit"]){
            FreeScheduleClassObject.action=@"Delete";
        }
    }
}


-(void) timetableButtonPressed:(UIButton *)sender
{
    if ([EnrollmentTableMode isEqualToString:@"Edit"] && !classalreadyreset) {
        
        
        if ([MyClass hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:@"Any" ExtendedType:@"fromclasskey"]) {
            UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Unable to switch to time table mode"] message:[MyClass returntitlewithtitle:@"Some of the class time has been used to extend other class"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                [missinginput dismissViewControllerAnimated:YES completion:nil];
                
            }];
            
            [missinginput addAction:OKAction];
            //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
        }else{
            UIAlertController *resetalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Enrollment Update"] message:[MyClass returntitlewithtitle:@"Important! All class records will be reset"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                
                sender.enabled=NO;
                
                if ([workingEnrollment.schedulekey intValue]==-2) {
                    workingEnrollment.startdate=@"";
                    tmpStartDateTime=@"";
                    workingEnrollment.noofclass=@"";
                    workingEnrollment.classtime=@"";
                    workingEnrollment.enddate=@"";
                    workingEnrollment.validity=@"";
                    [self resetFreeScheduleClassArraywithFreeScheduleClassArray:FreeScheduleClassArray];
                    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
                    [DetailLessonTable reloadData];
                }else{
                    workingEnrollment.startdate=@"TBD";
                    tmpStartDateTime=@"";
                    [self updatefreescheduleclassarraywithfield:@"StartDate" value:workingEnrollment.startdate];
                    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
                }
                
                
                
                [self popupclasstimetablewitheditmode:YES];
                
                //[self storeTmpField];
                
                ///showDatePicker=NO;
                [EnrollmentPopoverTable reloadData];
                [self adjusttablesize];
                classalreadyreset=TRUE;
            }];
            
            UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
                [resetalert dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [resetalert addAction:OKAction];
            [resetalert addAction:CancelAction];
            
            //[self presentViewController:resetalert animated:YES completion:nil];
                    [MyClass presentViewController:resetalert View:self];
        }
        
        

    }else{
        sender.enabled=NO;
        [self popupclasstimetablewitheditmode:NO];
        
        ///showDatePicker=NO;
        [EnrollmentPopoverTable reloadData];
        [self adjusttablesize];
    }
}

-(void) popupclasstimetablewitheditmode:(BOOL)editmode
{
    //BackupFreeScheduleClassArray=[[NSMutableArray alloc]initWithArray:FreeScheduleClassArray];
    BackupFreeScheduleClassArray=[self copyFreeScheduleClassArray:FreeScheduleClassArray];
    
    //popup class view record
    ClassTimeTableViewController *timetablepopover = (ClassTimeTableViewController *)[self->mainStoryboard instantiateViewControllerWithIdentifier: @"ClassTimeTableViewController"];
    if ([workingEnrollment.schedulekey isEqualToString:@"-1"]) { //weekly schedule
        timetablepopover.TimeTableMode=@"PopoverConsolidated";
        timetablepopover.FreeScheduleClassArray=nil;
        timetablepopover.EnrollmentMode=@"Weekly";
    }else if ([workingEnrollment.schedulekey isEqualToString:@"-2"]){ //free schedule
        timetablepopover.TimeTableMode=@"PopoverWeekly";
        timetablepopover.FreeScheduleClassArray=FreeScheduleClassArray;
        timetablepopover.EnrollmentMode=@"Free";
    }else{ //user defined schedule
        timetablepopover.TimeTableMode=@"PopoverWeekly";
        timetablepopover.FreeScheduleClassArray=nil;
        timetablepopover.EnrollmentMode=@"Schedule";
        timetablepopover.selectedschedulekey=workingEnrollment.schedulekey;
    }
    
    timetablepopover.sourcemode=@"Enrollment";
    timetablepopover.Subjectselected=workingEnrollment.subject;
    timetablepopover.studentkey=PopoverEnrollment.studentkey;
    
    if (editmode) {
        //FreeScheduleClassArray=[[NSMutableArray alloc]init];
        timetablepopover.draftenrollmentkey=PopoverEnrollment.enrollmentkey;
    }else{
        timetablepopover.draftenrollmentkey=[PopoverEnrollment.draft isEqualToString:@"Yes"]?PopoverEnrollment.enrollmentkey:@"NA";
    }
    
    
    timetablepopover.subjectallclassremarks=[self returnallclassremarkswithsubject:workingEnrollment.subject];
    timetablepopover.delegate=self;
    
    if (![workingEnrollment.instructor isEqualToString:@"TBD"] && ![workingEnrollment.instructor isEqualToString:@"Multi"] && ![workingEnrollment.instructor isEqualToString:@"TBF"]) {
        timetablepopover.preferredinstructor=workingEnrollment.instructor;
    }else{
        timetablepopover.preferredinstructor=@"";
    }
    
    timetablepopover.delegate=self;
    
    //[self presentViewController:timetablepopover animated:YES completion:nil];
    [MyClass presentViewController:timetablepopover View:self];

}


-(void)passTimeTableInformationwithstartdate:(NSString *)startdate classtime:(NSString *)classtime instructor:(NSString *)instructor classroom:(NSString *)classroom
{
    
    [self dismissViewControllerAnimated:YES completion:nil];
    
    workingEnrollment.startdate=startdate;
    workingEnrollment.classtime=classtime;

    if ([workingEnrollment.schedulekey intValue]>=0) {
        tmpStartDateTime=[NSString stringWithFormat:@"%@ %@",workingEnrollment.startdate,workingEnrollment.classtime];
    }else{
        workingEnrollment.classroom=classroom;
        workingEnrollment.instructor=instructor;
        tmpStartDateTime=workingEnrollment.startdate;
    }
    
    [self updatefreescheduleclassarraywithfield:@"StartDate" value:tmpStartDateTime];
    
    //check subject enrollment mode
    if ([((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).enrollmentmode isEqualToString:@"Month"]) {
        workingEnrollment.noofclass=[MyClass findnumberofclasstomonthend:tmpStartDateTime noofmonth:((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).standardnoofclassormonth schedulekey:workingEnrollment.schedulekey schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] roundingcheck:YES];
        [self updatefreescheduleclassarraywithfield:@"NoOfClass" value:workingEnrollment.noofclass];
        workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:tmpLevel noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
        [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    }
    
    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
    
    if ([EnrollmentTableMode isEqualToString:@"Edit"] && classalreadyreset) {
        for (int i=0; i<InitialFreeScheduleClassArray.count; i++) {
            ((FreeScheduleClass *)[InitialFreeScheduleClassArray objectAtIndex:i]).action=@"Delete";
            [FreeScheduleClassArray addObject:[InitialFreeScheduleClassArray objectAtIndex:i]];
        }
    }
    
    ///showDatePicker=NO;
    //[self storeTmpField];
    [self showsidewindowwithwindow:@"none"];
    [EnrollmentPopoverTable reloadData];
    [self adjusttablesize];
    
    
}

-(void) cancelselection
{
    FreeScheduleClassArray=[[NSMutableArray alloc]initWithArray:BackupFreeScheduleClassArray];
    
    if ([FreeScheduleClassArray isEqualToArray:InitialFreeScheduleClassArray]) {
        classalreadyreset=NO;
    }
    
    [self dismissViewControllerAnimated:NO completion:nil];
    
    
}

- (NSInteger)numberOfComponentsInPickerView:(UIPickerView *)pickerView
{
    if([selectedItem isEqualToString:@"ClassTime"]){
        return 2;
    }else if([selectedItem isEqualToString:@"DateTime"]){
        return 2;
    }else if ([selectedItem isEqualToString:@"CSClassTime"]) {
        return 3;
    }else if ([selectedItem isEqualToString:@"DLStartDateTime"]  || [selectedItem isEqualToString:@"DLMakeupStartDateTime"]){
        return 2;
    }else if([selectedItem isEqualToString:@"Level"]){
        if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
                if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                    return 1;
                }else{
                    return 2;
                }
        }else{
            return 1;
        }
        
    }else if ([selectedItem isEqualToString:@"DLLessonNumber"] || [selectedItem isEqualToString:@"StartingLesson"]){
        NSMutableArray *ln3Array=lessonArray[3];
        return ln3Array.count==0?3:4;
    }else if ([selectedItem isEqualToString:@"StandardPeriod"]) {
        if([workingEnrollment.enrollmentmode isEqualToString:@""]){
            return 1;
        }
        return 2;
    }else{
        return 1;
    }
}

- (NSInteger)pickerView:(UIPickerView *)pickerView numberOfRowsInComponent:(NSInteger)component
{
    if([selectedItem isEqualToString:@"StartDate"]){
        return 100000;
    }else if ([selectedItem isEqualToString:@"DLStartDateTime"] || [selectedItem isEqualToString:@"DLMakeupStartDateTime"]){
        /*if (component==0) {
            return 100000;
        }else */if (component==0){
            return [hourPickerViewMenu count];
        }else{
            return [minutePickerViewMenu count];
        }
    }else if([selectedItem isEqualToString:@"Level"]){
        
        if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
                if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                    return [levelmainPickerViewMenu count];
                }else{
                    if (component==0){
                        return [levelmainPickerViewMenu count];
                    }else{
                        return [levelctmPickerViewMenu count];
                    }
                }
        }else{
            return [pickerViewmenu count];
        }
        
    }else if([selectedItem isEqualToString:@"ClassTime"]){
        if (component==0){
            return [hourPickerViewMenu count];
        }else{
            return [minutePickerViewMenu count];
        }
    }else if([selectedItem isEqualToString:@"DetailsPayment"] || [selectedItem isEqualToString:@"EnrollmentDate"]|| [selectedItem isEqualToString:@"BillDate"] || [selectedItem isEqualToString:@"DropClassDate"]){
        return 100000;
    }else if ([selectedItem isEqualToString:@"EndDate"]){
        return 10000;
    }else if([selectedItem isEqualToString:@"CSClassTime"]){
        if (component==0){
            return [dayPickerViewMenu count];
        }else if (component==1){
            return [hourPickerViewMenu count];
        }else{
            return [minutePickerViewMenu count];
        }
    }else if([selectedItem isEqualToString:@"DateTime"]){
        if (component==0){
            return [hourPickerViewMenu count];
        }else{
            return [minutePickerViewMenu count];
        }
        
    }else if ([selectedItem isEqualToString:@"DLLessonNumber"]|| [selectedItem isEqualToString:@"StartingLesson"]){
        if (component==0) {
            return ((NSMutableArray *)lessonArray[0]).count;
        }else if (component==1) {
            return ((NSMutableArray *)lessonArray[1]).count;
        }else if (component==2) {
            return ((NSMutableArray *)lessonArray[2]).count;
        }else if (component==3) {
            return ((NSMutableArray *)lessonArray[3]).count;
        }
    }else if ([selectedItem isEqualToString:@"StandardPeriod"]) {
        if (component==0){
            return [standardnoofclassormontharray count];
        }else{
            return [enrollmentmodearray count];
        }
    }
    return [pickerViewmenu count];
    
}



- (CGFloat)pickerView:(UIPickerView *)pickerView widthForComponent:(NSInteger)component
{
    if([selectedItem isEqualToString:@"DateTime"]){
        if (component==0){
            return 30;
        }else{
            return 30;
        }
    }else if([selectedItem isEqualToString:@"ClassTime"]){
        return 60;
    }else if ([selectedItem isEqualToString:@"DLStartDateTime"] || [selectedItem isEqualToString:@"DLMakeupStartDateTime"]){
        if (component==0){
            return 40;
        }else{
            return 40;
        }
    }else if ([selectedItem isEqualToString:@"Level"]){
        if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
                if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                    return 260;
                }else{
                    return 80;
                }
        }else{
            return 260;
        }
    }else if([selectedItem isEqualToString:@"StartDate"]){
        return 190;
    }else if ([selectedItem isEqualToString:@"CSClassTime"]) {
        return 60;
    }else if([selectedItem isEqualToString:@"DLLessonNumber"]|| [selectedItem isEqualToString:@"StartingLesson"]){
        return 72.5;
    }else if ([selectedItem isEqualToString:@"StandardPeriod"]) {
        return 90;
    }else{
        return 260;
    }
}

-(BOOL) checklevelexistance
{
    if ([EnrollmentTableMode isEqualToString:@"Edit"] && ![MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {

        if (![self levelExistwithSubjectcode:workingEnrollment.subject Levelmain:tmpLevel]) {
            tmpLevel=@"";
            UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Edit Enrollment"] message:[MyClass returntitlewithtitle:@"The level no longer exists, please select another one"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                [missinginput dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [missinginput addAction:OKAction];
            //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
            return NO;
        }
    }
    return YES;
}

-(BOOL) checksubjectexistance
{
    if ([EnrollmentTableMode isEqualToString:@"Edit"]) {
        if (![self subjectExistwithSubjectcode:workingEnrollment.subject]) {
            [EnrollmentPopoverTable deselectRowAtIndexPath:[EnrollmentPopoverTable indexPathForSelectedRow] animated:YES];
            UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Edit Enrollment"] message:[MyClass returntitlewithtitle:@"Item cannot be updated because the subject no longer exists"] preferredStyle:UIAlertControllerStyleAlert];
            
            UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                [missinginput dismissViewControllerAnimated:YES completion:nil];
            }];
            
            [missinginput addAction:OKAction];
            //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
            return NO;
        }
    }
    return YES;
}

- (void)pickerView:(UIPickerView *)pickerView didSelectRow:(NSInteger)row inComponent:(NSInteger)component
{
    [self.view endEditing:YES];
    
    if ([selectedItem isEqualToString:@"ClassTime"]){
        NSString *oldclasstime=workingEnrollment.classtime;
        
        if (![workingEnrollment.classtime isEqualToString:[NSString stringWithFormat:@"%@:%@",[hourPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[minutePickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]]] && ![[NSString stringWithFormat:@"%@%@",[hourPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[minutePickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]] isEqualToString:@"Multi"]) {
            
            
            NSString *selectedhour=[hourPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]];
            NSString *selectedminute=[minutePickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]];
            if ([selectedhour isEqualToString:@"Multi"]) {
                selectedhour=[hourPickerViewMenu objectAtIndex:1];
            }
            
            if ([selectedminute isEqualToString:@""]) {
                selectedminute=[minutePickerViewMenu objectAtIndex:1];
            }

            //check if selected time is within operating hour
            NSString *selectedtime=[NSString stringWithFormat:@"%@%@",selectedhour,selectedminute];
            int classduration=[((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).classduration intValue];
            //classduration=(int)(classduration/60)*100+classduration%60;
            if ([selectedtime intValue]<[globalvariables.centerrecord.classstarttime intValue]) {
                UIAlertController *wrongTimeAlert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Enrollment Update"] message:[MyClass returntitlewithtitle:@"Class start time is outside center's opening hour"] preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [wrongTimeAlert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [wrongTimeAlert addAction:OKAction];
                //[self presentViewController:wrongTimeAlert animated:YES completion:nil];
                    [MyClass presentViewController:wrongTimeAlert View:self];
                
                [EnrollmentPopoverTable reloadData];
            }else if ([MyClass classendtimebeyondcenterendtimewithclassstarttime:selectedtime duration:classduration]){
                UIAlertController *wrongTimeAlert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Enrollment Update"] message:[MyClass returntitlewithtitle:@"Class end time is beyond center's closing hour"] preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [wrongTimeAlert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [wrongTimeAlert addAction:OKAction];
                //[self presentViewController:wrongTimeAlert animated:YES completion:nil];
                    [MyClass presentViewController:wrongTimeAlert View:self];
                
                [EnrollmentPopoverTable reloadData];
                
            }else{
                workingEnrollment.classtime=[NSString stringWithFormat:@"%@:%@",selectedhour,selectedminute];
                
                //ClassTimeLabel.text=workingEnrollment.classtime;
                
                [self updatefreescheduleclassarraywithfield:@"ClassTime" value:workingEnrollment.classtime];

            }
            
            if ([oldclasstime isEqualToString:@"Multi"]) {
                [hourPickerViewMenu removeObjectAtIndex:0];
                [minutePickerViewMenu removeObjectAtIndex:0];
                
                hourPresetRow=(int)[hourPickerViewMenu indexOfObject:[[workingEnrollment.classtime substringFromIndex:[workingEnrollment.classtime length]-5] substringToIndex:2]];
                minutePresetRow=(int)[minutePickerViewMenu indexOfObject:[workingEnrollment.classtime substringFromIndex:[workingEnrollment.classtime length]-2]];
                
                
                [myPickerView selectRow:hourPresetRow inComponent:0 animated:NO];
                [myPickerView selectRow:minutePresetRow inComponent:1 animated:NO];
                
                [myPickerView reloadAllComponents];
            }
            
            //[self storeTmpField];
            [EnrollmentPopoverTable reloadData];
            [self adjusttablesize];
            
        }
    }else if([selectedItem isEqualToString:@"Level"]){
        if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
                if ([[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]]isEqualToString:@"TBD"] || [[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]]isEqualToString:@"DT"]) {
                    tmpLevel=[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]] ;
                    
                    
                    //[self storeTmpField];
                    [EnrollmentPopoverTable reloadData];
                    
                }else{
                    if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                        tmpLevel=[NSString stringWithFormat:@"BTM%@",[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]]];
                        //[self storeTmpField];
                        [EnrollmentPopoverTable reloadData];
                    }else{
                        if ([[levelctmPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]] isEqualToString:@""]) {
                            tmpLevel=[NSString stringWithFormat:@"BTM%@",[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]]];
                            
                            workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]] noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
                            [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
                        }else{
                            if (![tmpLevel isEqualToString:[NSString stringWithFormat:@"BTM%@/CTM%@",[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[levelctmPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]]]) {
                                tmpLevel=[NSString stringWithFormat:@"BTM%@/CTM%@",[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[levelctmPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]];
                                
                                workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:[levelmainPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]] noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
                                [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
                            }
                        }
                        
                        //[self storeTmpField];
                        [EnrollmentPopoverTable reloadData];
                    }
                }
        }else{
            if (![tmpLevel isEqualToString:[pickerViewmenu objectAtIndex:row]]) {
                tmpLevel=[NSString stringWithFormat:@"%@",[pickerViewmenu objectAtIndex:[pickerView selectedRowInComponent:0]]];
                
                workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:[pickerViewmenu objectAtIndex:[pickerView selectedRowInComponent:0]] noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
                [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];;
                
