                [self updatenewschedulewithfiltertimearray:NO];
                
                [self clearenrollmentfield];
                
                [ScheduleTable reloadData];
                [self adjusttablesize];
            }
        }
    }else if([selectedItem isEqualToString:@"DateTime"]){
        //check if selected time is within operating hour
        
            NSString *selectedtime=[NSString stringWithFormat:@"%@%@",[hourPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[minutePickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]];
            //int classduration=[workingSubject.classduration intValue];
        int classduration=[((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).classduration intValue];
            if ([selectedtime intValue]<[globalvariables.centerrecord.classstarttime intValue]) {
                
                UIAlertController *wrongTimeAlert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Appointment"] message:[MyClass returntitlewithtitle:@"Class start time is outside center's opening hour"] preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [wrongTimeAlert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [wrongTimeAlert addAction:OKAction];
                //[self presentViewController:wrongTimeAlert animated:YES completion:nil];
                    [MyClass presentViewController:wrongTimeAlert View:self];
                
                
                [ScheduleTable reloadData];
            }else if ([MyClass classendtimebeyondcenterendtimewithclassstarttime:selectedtime duration:classduration]){
                UIAlertController *wrongTimeAlert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Appointment"] message:[MyClass returntitlewithtitle:@"Class end time is beyond center's closing hour"] preferredStyle:UIAlertControllerStyleAlert];
                
                UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                    [wrongTimeAlert dismissViewControllerAnimated:YES completion:nil];
                }];
                
                [wrongTimeAlert addAction:OKAction];
                //[self presentViewController:wrongTimeAlert animated:YES completion:nil];
                    [MyClass presentViewController:wrongTimeAlert View:self];
                
                [ScheduleTable reloadData];
                
            }else{
                workingScheduleDetails.classtime=[NSString stringWithFormat:@"%@:%@",[hourPickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:0]],[minutePickerViewMenu objectAtIndex:[pickerView selectedRowInComponent:1]]];
                //StartDateTimeLabel.text=[MyClass returndateformatDDMMMYYYYHHMMwithdate:[NSString stringWithFormat:@"%@ %@",workingScheduleDetails.dayofweek,workingATObject.DTtime]];

                [ScheduleTable reloadData];
                [self adjusttablesize];
            }

        
    }else if ([selectedItem isEqualToString:@"DLLessonNumber"]){
        NSMutableArray *selectedNumber=[[NSMutableArray alloc]init];
        [selectedNumber addObject:[((NSMutableArray *)lessonArray[0]) objectAtIndex:[pickerView selectedRowInComponent:0]]];
        [selectedNumber addObject:[((NSMutableArray *)lessonArray[1]) objectAtIndex:[pickerView selectedRowInComponent:1]]];
        [selectedNumber addObject:[@([pickerView selectedRowInComponent:2]+1) stringValue]];
        if ([pickerView numberOfComponents]==3) {
            [selectedNumber addObject:@"TBD"];
        }else{
            [selectedNumber addObject:[@([pickerView selectedRowInComponent:3]+1) stringValue]];
        }
        
        
        currentselectedfreescheduleclass.lesson=[selectedNumber componentsJoinedByString:@"/"];
        if ([currentselectedfreescheduleclass.action isEqualToString:@""]) {
            currentselectedfreescheduleclass.action=@"Edit";
        }
        [DetailLessonTable reloadData];
    }else if ([selectedItem isEqualToString:@"StartingLesson"]){
        NSMutableArray *selectedNumber=[[NSMutableArray alloc]init];
        [selectedNumber addObject:[((NSMutableArray *)lessonArray[0]) objectAtIndex:[pickerView selectedRowInComponent:0]]];
        [selectedNumber addObject:[((NSMutableArray *)lessonArray[1]) objectAtIndex:[pickerView selectedRowInComponent:1]]];
        [selectedNumber addObject:[@([pickerView selectedRowInComponent:2]+1) stringValue]];
        if ([pickerView numberOfComponents]==3) {
            [selectedNumber addObject:@"TBD"];
        }else{
            [selectedNumber addObject:[@([pickerView selectedRowInComponent:3]+1) stringValue]];
        }
        [self updatefreescheduleclassarraywithfield:@"StartingLesson" value:[selectedNumber componentsJoinedByString:@"/"]];
        //[DetailLessonTable reloadData];
    }else if([selectedItem isEqualToString:@"StandardPeriod"]){
        
        if(component==0){
            if(row==0){
                workingEnrollment.enrollmentmode=@"";
                workingEnrollment.standardnoofclassormonth=@"";
            }else{
                workingEnrollment.standardnoofclassormonth=[standardnoofclassormontharray objectAtIndex:row];
                if([workingEnrollment.enrollmentmode isEqualToString:@""]){
                    workingEnrollment.enrollmentmode=[enrollmentmodearray firstObject];
                }
            }
//            [pickerView reloadComponent:1];
        }else{
            workingEnrollment.enrollmentmode=[[enrollmentmodearray objectAtIndex:row] isEqualToString:@"Class"]?@"Class":@"Month";
        }
        
        
        //showStandardPeriodPicker=NO;
        
        //[self storeTmpField];
        
        [EnrollmentPopoverTable reloadData];
        [self adjusttablesize];
        
        
    }
}


-(void)textViewDidBeginEditing:(UITextView *)textView
{
    if (keyboardheight>0) {
        if (textView==paymentremarksText || textView==receiptremarksText || textView==invoiceremarksText) {
            CGPoint point = [textView.superview convertPoint:CGPointZero toView:DetailsPaymentTable];
            NSIndexPath *indexpath =[DetailsPaymentTable indexPathForRowAtPoint:point];
            
            CGRect rectInTableView = [DetailsPaymentTable rectForRowAtIndexPath:indexpath];
            
            if (rectInTableView.origin.y+rectInTableView.size.height-DetailsPaymentTable.frame.size.height>0) {
                [DetailsPaymentTable setContentOffset:CGPointMake(0, rectInTableView.origin.y+rectInTableView.size.height-DetailsPaymentTable.frame.size.height) animated:YES];
            }else{
                [DetailsPaymentTable setContentOffset:CGPointMake(0, 0) animated:YES];
            }
        }else{
            CGPoint point = [textView.superview convertPoint:CGPointZero toView:EnrollmentPopoverTable];
            NSIndexPath *indexpath =[EnrollmentPopoverTable indexPathForRowAtPoint:point];
            
            CGRect rectInTableView = [EnrollmentPopoverTable rectForRowAtIndexPath:indexpath];
            
            [EnrollmentPopoverTable setContentOffset:CGPointMake(0, rectInTableView.origin.y+rectInTableView.size.height-EnrollmentPopoverTable.frame.size.height) animated:YES];
        }
    }
}


-(void)textViewDidChange:(UITextView *)textView
{
    if (textView.tag==8) {
        CGPoint rootViewPoint = [textView.superview convertPoint:CGPointZero toView:EnrollmentPopoverTable];
        NSIndexPath *indexPath = [EnrollmentPopoverTable indexPathForRowAtPoint:rootViewPoint];
        
        MyTableViewCell *newcell=[EnrollmentPopoverTable cellForRowAtIndexPath:indexPath];
        
        CGSize size = [textView sizeThatFits:CGSizeMake(CGRectGetWidth(textView.frame), MAXFLOAT)];
        if (size.height>100) {
            newcell.layoutconstraint1.constant=100;
            textView.scrollEnabled=YES;
        }else{
            newcell.layoutconstraint1.constant=size.height;
            textView.scrollEnabled=NO;
        }
        workingEnrollment.remarks=textView.text;
        [EnrollmentPopoverTable beginUpdates];
        [EnrollmentPopoverTable endUpdates];
    }else if (textView==receiptremarksText){
        tmpreceiptremarks=textView.text;
    }else if (textView==paymentremarksText){
        tmppaymentremarks=textView.text;
    }else if (textView==invoiceremarksText){
        workingEnrollment.invoiceremarks=textView.text;
    }
}

-(void) updateschedulename:(UITextField *)textfield
{
    workingSchedule.name=textfield.text;
    globalvariables.addhocschedulerecord.name=workingSchedule.name;
    [EnrollmentPopoverTable reloadRowsAtIndexPaths:@[[NSIndexPath indexPathForRow:3 inSection:0]] withRowAnimation:UITableViewRowAnimationAutomatic];
    if ([textfield.text isEqualToString:@""]) {
        textfield.layer.borderColor=[UIColor redColor].CGColor;
    }else{
        textfield.layer.borderColor=[UIColor lightGrayColor].CGColor;
    }
}

-(void)offsettextfield:(UITextField *)sender
{

    if (sender==OneOffPercentageDiscountText) {
        if ([sender.text hasSuffix:@"%"]) {
            sender.text=[sender.text isEqualToString:@""]?@"":[sender.text substringToIndex:[sender.text length]-1];
        }
    }
    
    if (keyboardheight>0) {
        float y=DiscountTable.contentSize.height-DiscountTable.frame.size.height;
        if(y>0){
            [DiscountTable setContentOffset:CGPointMake(0, y) animated:YES];
        }
    }
    
}

