-(void) clearenrollmentfield
{
    workingEnrollment.startdate=@"";
    workingEnrollment.classtime=@"";
    tmpStartDateTime=@"";
    workingEnrollment.classday=@"";
    workingEnrollment.enddate=@"";
    workingEnrollment.validity=@"";
    workingEnrollment.instructor=@"";
    workingEnrollment.sinstructor=@"";
    workingEnrollment.classroom=@"";
    workingEnrollment.sinstructor=@"";
    
    [self updatefreescheduleclassarraywithfield:@"StartDate" value:@"TBD"];
    [self updatefreescheduleclassarraywithfield:@"ClassTime" value:@"TBD"];
    [self updatefreescheduleclassarraywithfield:@"Instructor" value:workingEnrollment.instructor];
    [self updatefreescheduleclassarraywithfield:@"SInstructor" value:workingEnrollment.sinstructor];
    [self updatefreescheduleclassarraywithfield:@"Classroom" value:workingEnrollment.classroom];
    
    //check subject enrollment mode
    if ([((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).enrollmentmode isEqualToString:@"Month"] || [workingEnrollment.schedulekey isEqualToString:@"-2"] || [workingSchedule.type isEqualToString:@"Fixed"]) {
        workingEnrollment.noofclass=@"";
        [self updatefreescheduleclassarraywithfield:@"NoOfClass" value:@"0"];
    }else{
        workingEnrollment.noofclass=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).standardnoofclassormonth;
        [self updatefreescheduleclassarraywithfield:@"NoOfClass" value:workingEnrollment.noofclass];
    }
    
    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
    
    //find school month
    workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:tmpLevel noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
    [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    
    [self closeallenrollmentpickers];
    [EnrollmentPopoverTable reloadData];

}

