-(NSString *) calculateMakeupQuota
{
    SubjectRecord *obj=[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey];
    NSString * makeup_quota_value=obj.makeup_quota_value;
    NSString *makeup_quota_unit=obj.makeup_quota_unit;
    
    if ([makeup_quota_value isEqualToString:@"-1"]) {
        return @"-1";
    }else{
        if ([makeup_quota_unit isEqualToString:@"P"]) {
            return [@((NSInteger)([makeup_quota_value floatValue]*[workingEnrollment.noofclass integerValue]/100)) stringValue];
        }else{//} if ([makeup_quota_unit isEqualToString:@"F"]){
            int noofmonth=ceil([MyClass findnumberofmonthwithschedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] freescheduleclassarray:FreeScheduleClassArray]);
            return [@([makeup_quota_value floatValue]*noofmonth) stringValue];
        }
    }
}

