-(BOOL) checkvalidfeeinput:(NSString *)input
{
    NSString *decimalRegex = @"^(?:|-)(?:|0|[1-9]\\d*)(?:\\.\\d*)?$";
    NSPredicate *regexPredicate = [NSPredicate predicateWithFormat:@"SELF MATCHES %@", decimalRegex];
    
    if ([regexPredicate evaluateWithObject: input]){
        //Matches
        return TRUE;
    }else{
        return FALSE;
    }
}


-(NSMutableArray *) copyFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    NSMutableArray *returnresult=[[NSMutableArray alloc]init];
    for (int i=0; i<freescheduleclassarray.count; i++) {
        FreeScheduleClassObject=[freescheduleclassarray objectAtIndex:i];
        [returnresult addObject:[[FreeScheduleClass alloc]initFreeScheduleClassWithclasskey:FreeScheduleClassObject.classkey subject:FreeScheduleClassObject.subject classdate:FreeScheduleClassObject.classdate classtime:FreeScheduleClassObject.classtime instructor:FreeScheduleClassObject.instructor classroom:FreeScheduleClassObject.classroom attendance:FreeScheduleClassObject.attendance makeupdate:FreeScheduleClassObject.makeupdate makeuptime:FreeScheduleClassObject.makeuptime makeupinstructor:FreeScheduleClassObject.makeupinstructor makeupclassroom:FreeScheduleClassObject.makeupclassroom makeupattendance:FreeScheduleClassObject.makeupattendance classremarks:FreeScheduleClassObject.classremarks allclassremarks:FreeScheduleClassObject.allclassremarks action:FreeScheduleClassObject.action classtype:@"Class" leavenaturelistkey:FreeScheduleClassObject.leavenaturelistkey lesson:FreeScheduleClassObject.lesson sinstructor:FreeScheduleClassObject.sinstructor makeupsinstructor:FreeScheduleClassObject.makeupsinstructor locked:FreeScheduleClassObject.locked]];
    }
    
    return returnresult;
}

-(BOOL) checkvalidpercentagediscountinput:(NSString *)input
{
    NSString *decimalRegex = @"^(?:|-)(?:|0|[1-9]\\d*)(?:\\.\\d*)?$";
    NSPredicate *regexPredicate = [NSPredicate predicateWithFormat:@"SELF MATCHES %@", decimalRegex];
    
    if ([input isEqualToString:@""]) {
        return TRUE;
    }else{
        if ([input hasSuffix:@"%"]) {
            if ([regexPredicate evaluateWithObject: [input substringToIndex:[input length]-1]]){
                //Matches
                return TRUE;
            }else{
                return FALSE;
            }
        }else{
            if ([regexPredicate evaluateWithObject: input]){
                //Matches
                return TRUE;
            }else{
                return FALSE;
            }
        }
    }
}


-(void) checkdetailspaymentvalue:(UITextField *)sender
{
    if (![self checkvalidfeeinput:sender.text]){
        sender.text=@"";
    }
    tmppaidamount=sender.text;
    
}

