                                if ([FreeScheduleClassObject.action isEqualToString:@"Add"]) {
                                    [FreeScheduleClassArray removeObjectAtIndex:i];
                                    i-=1;
                                }else{
                                    FreeScheduleClassObject.action=@"Delete";
                                }
                                
                                break;
