                                    [FreeScheduleClassArray addObject:tmpfreescheduleclassobject];
                                    break;
                                }else if ([FreeScheduleClassObject.classdate isEqualToString:tmpfreescheduleclassobject.classdate] && [FreeScheduleClassObject.classtime isEqualToString:tmpfreescheduleclassobject.classtime] && [FreeScheduleClassObject.subject isEqualToString:tmpfreescheduleclassobject.subject] && [FreeScheduleClassObject.instructor isEqualToString:tmpfreescheduleclassobject.instructor] && [FreeScheduleClassObject.classroom isEqualToString:tmpfreescheduleclassobject.classroom] && ![FreeScheduleClassObject.action isEqualToString:@"Delete"]) {
                                    break;
                                }else if (i==FreeScheduleClassArray.count-1){
                                    [FreeScheduleClassArray addObject:tmpfreescheduleclassobject];
                                    break;
                                }
                            }
                        }
                    }

                    //[self sortdatetimeforfreescheduleclassarraydatetime];
                }else{
                    tmpStartDateTime=@"";
                    workingEnrollment.noofclass=@"";
                    [self updatefreescheduleclassarraywithfield:@"NoOfClass" value:workingEnrollment.noofclass];
                    [self showsidewindowwithwindow:@"none"];
                    [self adjusttablesize];
                    
                    UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Enrollment Update"] message:[MyClass returntitlewithtitle:@"No class date available for the selected schedule"] preferredStyle:UIAlertControllerStyleAlert];
                    
                    UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
                        [erroralert dismissViewControllerAnimated:YES completion:nil];
                    }];
                    
                    [erroralert addAction:OKAction];
                    //[self presentViewController:erroralert animated:YES completion:nil];
                    [MyClass presentViewController:erroralert View:self];
                }
            }
        }
        
    }else if([field isEqualToString:@"StartingLesson"]){
        if (![workingEnrollment.noofclass isEqualToString:@""]) {
            
            if ([value isEqualToString:@""]) {
                //clear
                for (long i=0; i<FreeScheduleClassArray.count; i++) {
                    FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
                    if (![FreeScheduleClassObject.action isEqualToString:@"Delete"]) {
                        if(![FreeScheduleClassObject.lesson isEqualToString:@""]){
                            FreeScheduleClassObject.lesson=@"";
                            if ([FreeScheduleClassObject.action isEqualToString:@""]) {
                                FreeScheduleClassObject.action=@"Edit";
                            }
                        }
                    }
                }
            }else{
                long l=0;
                for (long i=0; i<FreeScheduleClassArray.count; i++) {
                    FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
                    if (![FreeScheduleClassObject.action isEqualToString:@"Delete"]) {
                        NSString *newlesson=[MyClass returnLessonWithSubject:workingEnrollment.subject StartingLesson:value Offset:l];
                        l++;
                        if(![FreeScheduleClassObject.lesson isEqualToString:newlesson]){
                            FreeScheduleClassObject.lesson=newlesson;
                            if ([FreeScheduleClassObject.action isEqualToString:@""]) {
                                FreeScheduleClassObject.action=@"Edit";
                            }
                        }
                    }
                }
            }
        }
    }
    
    [self sortdatetimeforfreescheduleclassarraydatetimewithfreescheduleclassarray:FreeScheduleClassArray];
    
    [DetailLessonTable reloadData];
    
    return YES;
}

-(NSString *) returnNextLessonWithFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    FreeScheduleClass *lastclass;
    for (long i=freescheduleclassarray.count-1;i>=0;i--){
        FreeScheduleClass *obj=[freescheduleclassarray objectAtIndex:i];
        if (![obj.action isEqualToString:@"Delete"]) {
            lastclass=obj;
            break;
        }
    }
    
    NSString *newlesson=@"";
    if (lastclass) {
        newlesson=[MyClass returnLessonWithSubject:workingEnrollment.subject StartingLesson:lastclass.lesson Offset:1];
    }
    return newlesson;
}

-(void) updatefreesscheduleclassarrayandtuitionwithschedule:(ScheduleRecord *)schedulerecord
{
    [self updatefreescheduleclassarraywithschedule:schedulerecord];
    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
    
    //[self checklevelexistance];
    
    //find school month
    workingEnrollment.tuitionfee=[self calculateTuitionFeeWithClass:workingEnrollment.subject Levelmain:tmpLevel noOfClass:workingEnrollment.noofclass startdatetime:tmpStartDateTime freescheduleclassarray:FreeScheduleClassArray];
    [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    
    [ScheduleTable reloadData];
    [EnrollmentPopoverTable reloadData];
}

-(void) updatefreescheduleclassarraywithschedule:(ScheduleRecord *)schedulerecord
{
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        FreeScheduleClass *object=[FreeScheduleClassArray objectAtIndex:i];
        if ([object.action isEqualToString:@"Add"]) {
            [FreeScheduleClassArray removeObjectAtIndex:i];
            i--;
        }else{
            object.action=@"Delete";
        }
    }
    
    for (int i=0; i<schedulerecord.daytimearray.count; i++) {
        ScheduleDetailsRecord *obj=[schedulerecord.daytimearray objectAtIndex:i];
        [FreeScheduleClassArray addObject:[[FreeScheduleClass alloc]initFreeScheduleClassWithclasskey:@"" subject:workingEnrollment.subject classdate:[MyClass convertDateFormatWithDate:obj.dayofweek FromDateFormat:@"yyyy-MM-dd" ToDateFormat:@"dd-MMM-yyyy" Translate:NO] classtime:obj.classtime instructor:obj.instructor classroom:obj.classroom attendance:globalvariables.centerrecord.defaultattendancestatus makeupdate:@"" makeuptime:@"" makeupinstructor:@"" makeupclassroom:@"" makeupattendance:@"" classremarks:@"" allclassremarks:[self returnallclassremarkswithsubject:workingEnrollment.subject] action:@"Add" classtype:@"Class" leavenaturelistkey:@"0" lesson:@"" sinstructor:obj.sinstructor makeupsinstructor:@"" locked:NO]];
    }
    
    [self sortdatetimeforfreescheduleclassarraydatetimewithfreescheduleclassarray:FreeScheduleClassArray];
    
    workingEnrollment.noofclass=[@(schedulerecord.daytimearray.count) stringValue];
    
    [DetailLessonTable reloadData];
}

- (BOOL) checkifmultipleclassonsameday
{
    NSMutableArray *classdatearray=[[NSMutableArray alloc]init];
    for (int i=0; i<FreeScheduleClassArray.count; i++) {
        FreeScheduleClassObject=[FreeScheduleClassArray objectAtIndex:i];
        if (![FreeScheduleClassObject.action isEqualToString:@"Delete"]) {
            if ([FreeScheduleClassObject.classdate isEqualToString:@"TBD"]) {
                [classdatearray addObject:FreeScheduleClassObject.classdate];
            }else if ([classdatearray containsObject:FreeScheduleClassObject.classdate]) {
                break;
            }else{
                [classdatearray addObject:FreeScheduleClassObject.classdate];
            }
        }
    }
    
    if (classdatearray.count<[MyClass returnnoofclasswithfreescheduleclassarray:FreeScheduleClassArray]) {
        //more than 1 class on same days
        UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"More than 1 class happen(s) on same day"] message:[MyClass returntitlewithtitle:@"Class time is not able to be changed"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [erroralert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [erroralert addAction:OKAction];
        [self presentViewController:erroralert animated:YES completion:nil];
        return TRUE;
    }else{
        return FALSE;
    }
}


-(void) sortdatetimeforfreescheduleclassarraydatetimewithfreescheduleclassarray:(NSMutableArray *)array
{
    NSMutableArray *freescheduleclassarray=[[NSMutableArray alloc]initWithArray:array];
    
    for (int i=0; i<freescheduleclassarray.count; i++) {
        if ([((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).attendance isEqualToString:@"Makeup"] && ![((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate isEqualToString:@"TBD"] && ![((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate isEqualToString:@""]) {
            NSString *tmpclassdate=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate;
            NSString *tmpclasstime=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classtime;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classtime=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeuptime;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).attendance=@"MakeupSwap";
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate=tmpclassdate;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeuptime=tmpclasstime;
        }
        
        ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate=[MyClass convertDDMMMYYYYtoYYYYMMDDwithdate:((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate];
    }
    
    NSSortDescriptor *sortByDate = [NSSortDescriptor sortDescriptorWithKey:@"classdate" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSSortDescriptor *sortByTime = [NSSortDescriptor sortDescriptorWithKey:@"classtime" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSSortDescriptor *sortByAction = [NSSortDescriptor sortDescriptorWithKey:@"action" ascending:YES selector:@selector(localizedStandardCompare:)];
    NSArray *sortDescriptors = @[sortByDate, sortByTime,sortByAction];
    freescheduleclassarray = [NSMutableArray arrayWithArray:[freescheduleclassarray sortedArrayUsingDescriptors:sortDescriptors]];
    
    
    for (int i=0; i<freescheduleclassarray.count; i++) {
        ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate=[MyClass convertYYYYMMDDtoDDMMMYYYYwithdate:((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate];
        
        if ([((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).attendance isEqualToString:@"MakeupSwap"]) {
            NSString *tmpclassdate=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate;
            NSString *tmpclasstime=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classtime;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classdate=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).classtime=((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeuptime;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).attendance=@"Makeup";
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeupdate=tmpclassdate;
            ((FreeScheduleClass *)[freescheduleclassarray objectAtIndex:i]).makeuptime=tmpclasstime;
        }
        
        
        
        if (showDetailLesson && selectedlessonrow>=0 && [[freescheduleclassarray objectAtIndex:i] isEqual:currentselectedfreescheduleclass]) {
            selectedlessonrow=i;
        }
    }
    
    [array removeAllObjects];
    [array addObjectsFromArray:freescheduleclassarray];
    
    if (showDetailLesson && selectedlessonrow>=0 && currentselectedfreescheduleclass) {
        if (![DetailLessonTable.indexPathsForVisibleRows containsObject:[NSIndexPath indexPathForRow:selectedlessonrow inSection:0]]) {
            [DetailLessonTable scrollToRowAtIndexPath:[NSIndexPath indexPathForRow:selectedlessonrow inSection:0] atScrollPosition:UITableViewScrollPositionMiddle animated:NO];
        }
    }
    
}

-(void) sortFilteredSubjectArray
{
    NSSortDescriptor *sortBySubjectName;
    if ([globalvariables.language isEqualToString:@"English"]) {
        sortBySubjectName = [NSSortDescriptor sortDescriptorWithKey:@"subject_englishname" ascending:YES selector:@selector(localizedStandardCompare:)];
    }else{
        sortBySubjectName = [NSSortDescriptor sortDescriptorWithKey:@"subject_chinesename" ascending:YES selector:@selector(localizedStandardCompare:)];
    }
    
    NSArray *sortDescriptors = @[sortBySubjectName];
    filteredSubjectArray = [NSMutableArray arrayWithArray:[filteredSubjectArray sortedArrayUsingDescriptors:sortDescriptors]];
}

-(void) sortFilteredScheduleArray
{
    //remove expired schedule
    ScheduleRecord *object;
    for(int i=0;i<filteredScheduleArray.count;i++){
        object=[filteredScheduleArray objectAtIndex:i];
        if (!object.active || (![object.enddate isEqualToString:@""] && ![object.schedulekey isEqualToString:@"999999999"] && [[MyClass convertToNSDateWithDate:[NSString stringWithFormat:@"%@ 23:59:59",object.enddate] DateFormat:@"dd-MMM-yyyy HH:mm:ss"] compare:[NSDate date]]==NSOrderedAscending)) {
            [filteredScheduleArray removeObjectAtIndex:i];
            i--;
        }
    }
    
    
    NSSortDescriptor *sortBySubjectName = [NSSortDescriptor sortDescriptorWithKey:@"name" ascending:YES selector:@selector(localizedStandardCompare:)];

    NSArray *sortDescriptors = @[sortBySubjectName];
    filteredScheduleArray = [NSMutableArray arrayWithArray:[filteredScheduleArray sortedArrayUsingDescriptors:sortDescriptors]];
}



-(NSString *) returnallclassremarkswithsubject:(NSString *)subject
{
    NSString *allclassremarks=@"";
    AllClassRemarksRecord *allclassremarksobject=[[AllClassRemarksRecord alloc]init];
    for (long i=0; i<AllClassRemarksArray.count; i++) {
        allclassremarksobject=[AllClassRemarksArray objectAtIndex:i];
        if ([allclassremarksobject.subject isEqualToString:subject]) {
            allclassremarks=allclassremarksobject.allclassremarks;
            break;
        }
        
    }
    return allclassremarks;
    
}



-(BOOL) validateClassWithFreeScheduleArray:(NSMutableArray *)freescheduleclassarray
{
    if ([PopoverEnrollment.status isEqualToString:@"Voided"]) {
        classvalidatemessage=[[ClassValidateMessage alloc]initClassValidateMessagewithoverenrollmentmessage:@"" sameinstructormulticlassmessage:@"" alreadyenrolledmessage:@"" sameclassroommulticlassmessage:@"" hasextendedchildclassmessage:@"" classroomexceedcapacitymessage:@"" makeupquotaexceedmessage:@""];
        return YES;
    }
    
    NSString *tmpenrollmentkey;
    if ([EnrollmentTableMode isEqualToString:@"Renewal"]) {
        tmpenrollmentkey=@"";
    }else{
        tmpenrollmentkey=PopoverEnrollment.enrollmentkey?PopoverEnrollment.enrollmentkey:@"";
    }
    
    classvalidatemessage=[MyClass validateClassWithFreeScheduleArray:freescheduleclassarray studentkey:PopoverStudent.studentkey enrollmentkey:tmpenrollmentkey];
    classvalidatestatus=[[ClassValidateStatus alloc]initClassValidateStatuswithoverenrollmentstatus:@"" sameinstructormulticlassstatus:@"" alreadyenrolledstatus:@"" sameclassroommulticlassstatus:@"" hasextendedchildclassstatus:@"" classroomexceedcapacitystatus:@"" makeupquotaexceedstatus:@""];
    
    return YES;

}


