-(void) retreieveschoolcalendarday
{
    //[MyClass getLatestDataSetv2withParameters:@"calendar" Centerkeys:globalvariables.centerrecord.centerkey completionBlock:nil];

    hourPickerViewMenu=[[NSMutableArray alloc]init];
    minutePickerViewMenu=[[NSMutableArray alloc]init];

    [MyClass loadHourPickerViewMenu:hourPickerViewMenu];
    
    for (int i=0; i<60; i+=[globalvariables.centerrecord.classtimeinterval intValue]) {
        [minutePickerViewMenu addObject:[NSString stringWithFormat:@"%02i",i]];
    }
    dayPickerViewMenu=[[NSMutableArray alloc]initWithObjects:@"Mon",@"Tue",@"Wed",@"Thu",@"Fri",@"Sat",@"Sun", nil];
    
}


-(BOOL) determinelastclassinstructorandtimeandclassroomanddate
{
    
    NSString *strURL;
    
    strURL=[NSString stringWithFormat:@"%@?centerdb=%@&centerkey=%@&action=findlastclassinstructorandtimeanddate&enrollmentkey=%@&subject=%@&studentkey=%@&schedulekey=%@",globalvariables.generalphpfullpath,globalvariables.centerrecord.centerdb,globalvariables.centerrecord.centerkey,PopoverEnrollment.enrollmentkey,[MyClass enurlstring:PopoverEnrollment.subject],PopoverEnrollment.studentkey,PopoverEnrollment.schedulekey];
    
    __block BOOL result=FALSE;
    __block NSMutableArray *jsonresponse;
    
    [MyClass callGETwithURL:strURL completionBlock:^(BOOL succeeded, NSData *data) {
        if (succeeded) {
            result=TRUE;
            NSDictionary *jsonreturned=[NSJSONSerialization JSONObjectWithData:data options:(kNilOptions) error:nil];
            jsonresponse = jsonreturned[@"content"];
        }
    }];

        
    if (result && jsonresponse.count>0) {
        lastclassinstructor=[[jsonresponse objectAtIndex:0] objectForKey:@"instructor"];
        lastclasssinstructor=[[jsonresponse objectAtIndex:0] objectForKey:@"sinstructor"];
        lastclasstime=[[jsonresponse objectAtIndex:0] objectForKey:@"classtime"];
        lastclassroom=[[jsonresponse objectAtIndex:0] objectForKey:@"classroom"];
        lastclassdate=[[jsonresponse objectAtIndex:0] objectForKey:@"classdate"];
        lastlesson=[[jsonresponse objectAtIndex:0] objectForKey:@"lesson"];
        
        if (![lastclassinstructor isEqualToString:@"TBD"]) {
            if (![((Staff *)[MyClass returnstaffrecordwithusername:lastclassinstructor]).status isEqualToString:@"Yes"]) {
                lastclassinstructor=@"";
            }
        }
        
        if (![lastclasssinstructor isEqualToString:@"TBD"]) {
            if (![((Staff *)[MyClass returnstaffrecordwithusername:lastclasssinstructor]).status isEqualToString:@"Yes"]) {
                lastclasssinstructor=@"";
            }
        }
    }else{
        lastclassinstructor=@"";
        lastclasssinstructor=@"";
        lastclasstime=@"";
        lastclassroom=@"";
        lastclassdate=@"";
        lastlesson=@"";
    }
    
    return result;
}

-(NSString *) retrievemaxsubjectlevelwithsubject:(NSString *)subject
{
    //MaxLevelRecord *maxsubjectlevelobject=[[MaxLevelRecord alloc]init];
    
    NSString *maxlevelctm=@"";
    NSString *maxlevelmain=@"";

    LastLevelRecord *lastlevelobject=[leveldictionary objectForKey:subject];
    if (lastlevelobject) {
        maxlevelmain=lastlevelobject.levelmain;
        maxlevelctm=lastlevelobject.levelctm;
    }
    
    
    if ([MyClass isEyeLevelMathWithSubject:subject]) {
        if ([maxlevelmain isEqualToString:@""]) {
            return @"";
        }else if ([maxlevelctm isEqualToString:@""]) {
            return [NSString stringWithFormat:@"BTM%@",maxlevelmain];
        }else{
            return [NSString stringWithFormat:@"BTM%@/CTM%@",maxlevelmain,maxlevelctm];
        }
    }else{
        if ([maxlevelctm isEqualToString:@""]) {
            //check if only one level
            NSMutableArray *subjectlevelarray=[[NSMutableArray alloc]init];
//            subjectlevelarray=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).levelArray;;
            subjectlevelarray=[MyClass returnLevelOnlyArrayWithSubject:workingEnrollment.subject];
            if (subjectlevelarray.count==1) {
                return [subjectlevelarray objectAtIndex:0];
            }else{
                return maxlevelmain;
            }
        }else{
            return maxlevelmain;
        }
    }
}

-(void)setTBDDatebuttonpressed:(id)sender
{
    
    if ([MyClass hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:@"Any" ExtendedType:@"fromclasskey"]) {
        UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Unable to reset start date"] message:[MyClass returntitlewithtitle:@"Some of the class time has been used to extend other class"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [missinginput dismissViewControllerAnimated:YES completion:nil];
            
        }];
        
        [missinginput addAction:OKAction];
        //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
    }else if (!classalreadyreset){
        UIAlertController *resetalert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Enrollment Update"] message:[MyClass returntitlewithtitle:@"Important! All class records will be reset"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
            classalreadyreset=TRUE;
            
            workingEnrollment.startdate=@"";
            workingEnrollment.enddate=@"";
            workingEnrollment.classday=@"";
            tmpStartDateTime=@"";
            
            [self updatefreescheduleclassarraywithfield:@"StartDate" value:workingEnrollment.startdate];
            [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
            workingEnrollment.validity=[self returnvalidityvalue];
            
            //[self storeTmpField];
            
            ///showDatePicker=NO;
            [self showsidewindowwithwindow:@""];
            [EnrollmentPopoverTable reloadData];
            [self adjusttablesize];
        }];
        
        UIAlertAction *CancelAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"Cancel"] style:UIAlertActionStyleDefault handler:^(UIAlertAction *action) {
            [resetalert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [resetalert addAction:OKAction];
        [resetalert addAction:CancelAction];
        
        //[self presentViewController:resetalert animated:YES completion:nil];
        [MyClass presentViewController:resetalert View:self];
        
    }else{
        workingEnrollment.startdate=@"";
        workingEnrollment.enddate=@"";
        workingEnrollment.classday=@"";
        tmpStartDateTime=@"";
        [self updatefreescheduleclassarraywithfield:@"StartDate" value:workingEnrollment.startdate];
        if ([((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).enrollmentmode isEqualToString:@"Month"]) {
            workingEnrollment.noofclass=@"";
            [self updatefreescheduleclassarraywithfield:@"NoOfClass" value:@""];
        }

        [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
        workingEnrollment.validity=[self returnvalidityvalue];
        
        //[self storeTmpField];
        
        ///showDatePicker=NO;
        [EnrollmentPopoverTable reloadData];
        [self adjusttablesize];
    }
    

    
}

-(void)setTBDTimebuttonpressed:(id)sender
{
    workingEnrollment.classtime=@"TBD";
    [self updatefreescheduleclassarraywithfield:@"ClassTime" value:workingEnrollment.classtime];
    [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
    
    //[self storeTmpField];
    
    showTimePicker=NO;
    [EnrollmentPopoverTable reloadData];
    [self adjusttablesize];
}

-(BOOL) hasStartDateTBDclasseswithFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    BOOL result=FALSE;
    
    FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
    for (long i=0; i<freescheduleclassarray.count; i++) {
        freescheduleclassobject=[freescheduleclassarray objectAtIndex:i];
        if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
            if ([freescheduleclassobject.classdate isEqualToString:@"TBD"]) {
                result=TRUE;
                break;
            }
            
        }
    }
    return result;
}

-(BOOL) hasMakeupdateTBDwithFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    BOOL result=FALSE;
    
    FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
    for (long i=0; i<freescheduleclassarray.count; i++) {
        freescheduleclassobject=[freescheduleclassarray objectAtIndex:i];
        if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
            if ([freescheduleclassobject.attendance isEqualToString:@"Makeup"]){
                if ([freescheduleclassobject.makeupdate isEqualToString:@""]) {
                    result=TRUE;
                    break;
                }
            }
        }
    }
    return result;
}

-(BOOL) isRegularclasseswithFreeScheduleClassArray:(NSMutableArray *)freescheduleclassarray
{
    BOOL result=TRUE;
    
    if(freescheduleclassarray.count==0){
        return FALSE;
    }
    
    if([workingEnrollment.schedulekey intValue]==-2){
        return false;
    }else if ([workingEnrollment.schedulekey intValue]<0) {
        if ([workingEnrollment.classday isEqualToString:@"Multi"] || [workingEnrollment.classtime isEqualToString:@"Multi"]) {
            result = FALSE;
        }else{
            long noofclass=[MyClass returnnoofclasswithfreescheduleclassarray:freescheduleclassarray];
            NSMutableArray *regularclassdatearray=[[NSMutableArray alloc]init];
            NSMutableArray *dateOnlyArray=[[NSMutableArray alloc]init];

            regularclassdatearray=[MyClass findnextlessonwithdatetime:workingEnrollment.startdate dayofweek:[MyClass returndayofweek:workingEnrollment.startdate] schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] nooflesson:noofclass includebasedate:YES excludescheduleenddatecheck:NO manualselection:NO];
            
            for (int i=0;i<regularclassdatearray.count;i++){
                [dateOnlyArray addObject:((LessonRecord2 *)[regularclassdatearray objectAtIndex:i]).datetime];
            }
            
            FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
            for (long i=0; i<freescheduleclassarray.count; i++) {
                freescheduleclassobject=[freescheduleclassarray objectAtIndex:i];
                if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
                    if (![dateOnlyArray containsObject:freescheduleclassobject.classdate]) {
                        result=FALSE;
                        break;
                    }else{
                        [dateOnlyArray removeObject:freescheduleclassobject.classdate];
                    }
                }
            }
        }
    }else{
        long noofclass=[MyClass returnnoofclasswithfreescheduleclassarray:freescheduleclassarray];
        NSMutableArray *regularclassdatearray=[[NSMutableArray alloc]init];
        NSMutableArray *dateOnlyArray=[[NSMutableArray alloc]init];
        
        NSString *startdatetime=[NSString stringWithFormat:@"%@ %@",((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:freescheduleclassarray]).classdate,((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:freescheduleclassarray]).classtime];

        regularclassdatearray=[MyClass findnextlessonwithdatetime:startdatetime dayofweek:nil schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] nooflesson:noofclass includebasedate:YES excludescheduleenddatecheck:YES manualselection:NO];
        
        for (int i=0;i<regularclassdatearray.count;i++){
            [dateOnlyArray addObject:((LessonRecord2 *)[regularclassdatearray objectAtIndex:i]).datetime];
        }

        FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
        for (long i=0; i<freescheduleclassarray.count; i++) {
            freescheduleclassobject=[freescheduleclassarray objectAtIndex:i];
            if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
                if (![dateOnlyArray containsObject:[NSString stringWithFormat:@"%@ %@",freescheduleclassobject.classdate,freescheduleclassobject.classtime]]) {
                    result=FALSE;
                    break;
                }else{
                    [dateOnlyArray removeObject:[NSString stringWithFormat:@"%@ %@",freescheduleclassobject.classdate,freescheduleclassobject.classtime]];
                }
            }
        }
    }
    
    return result;
}

