-(void) addRegularFreeScheduleClasswithNoOfClass:(long)noofclass
{
    
    NSString *tmpclasstime;
    NSString *tmpinstructor;
    NSString *tmpsinstructor;
    NSString *tmpclassroom;

    long existingnoofclass=[MyClass returnnoofclasswithfreescheduleclassarray:FreeScheduleClassArray];
    BOOL undeletedclassfound;
    
    NSString *firstclass;
    if ([workingEnrollment.schedulekey intValue]<0) {
        firstclass=workingEnrollment.startdate;
    }else{
        firstclass=[NSString stringWithFormat:@"%@ %@",((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classdate,((FreeScheduleClass *)[self returnfirstfreescheduleclasswithfreescheduleclassarray:FreeScheduleClassArray]).classtime];
    }


    NSMutableArray *tmpnextlessonarray=[MyClass findnextlessonwithdatetime:firstclass dayofweek:[MyClass returndayofweek:firstclass] schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] nooflesson:existingnoofclass+noofclass includebasedate:YES excludescheduleenddatecheck:YES manualselection:NO];
    
    
    if (tmpnextlessonarray) {
        //[tmpnextlessonarray insertObject:firstclass atIndex:0];
        
        for (long i=0; i<noofclass; i++) {
            //check and undelete class with same startdate
            undeletedclassfound=FALSE;

            
            //add new class
            if (!undeletedclassfound) {
                if ([workingEnrollment.schedulekey intValue]<0) {
                    if ([workingEnrollment.classtime isEqualToString:@""] || [workingEnrollment.classtime isEqualToString:@"TBF"] || [workingEnrollment.classtime isEqualToString:@"Multi"]) {
                        tmpclasstime=@"TBD";
                    }else{
                        tmpclasstime=workingEnrollment.classtime;
                    }
                    
                    if ([workingEnrollment.instructor isEqualToString:@""] || [workingEnrollment.instructor isEqualToString:@"TBD"] || [workingEnrollment.instructor isEqualToString:@"TBF"] || [workingEnrollment.instructor isEqualToString:@"Multi"]) {
                        tmpinstructor=@"TBD";
                    }else{
                        tmpinstructor=workingEnrollment.instructor;// InstructorLabel.text;
                    }
                    
                    if ([workingEnrollment.sinstructor isEqualToString:@""] || [workingEnrollment.sinstructor isEqualToString:@"TBD"] || [workingEnrollment.sinstructor isEqualToString:@"TBF"] || [workingEnrollment.sinstructor isEqualToString:@"Multi"]) {
                        tmpsinstructor=@"TBD";
                    }else{
                        tmpsinstructor=workingEnrollment.sinstructor;// InstructorLabel.text;
                    }
                    
                    if ([workingEnrollment.classroom isEqualToString:@""] || [workingEnrollment.classroom isEqualToString:@"TBD"] || [workingEnrollment.classroom isEqualToString:@"TBF"] || [workingEnrollment.classroom isEqualToString:@"Multi"]) {
                        tmpclassroom=@"TBD";
                    }else{
                        tmpclassroom=workingEnrollment.classroom;// InstructorLabel.text;
                    }
                }else{
                    tmpclasstime=[((LessonRecord2 *)[tmpnextlessonarray objectAtIndex:i+existingnoofclass]).datetime substringFromIndex:12];
                    tmpclassroom=((LessonRecord2 *)[tmpnextlessonarray objectAtIndex:i+existingnoofclass]).classroom;
                    tmpinstructor=((LessonRecord2 *)[tmpnextlessonarray objectAtIndex:i+existingnoofclass]).instructor;
                }
                
                NSString *newlesson=[self returnNextLessonWithFreeScheduleClassArray:FreeScheduleClassArray];
                
                [FreeScheduleClassArray addObject:[[FreeScheduleClass alloc]initFreeScheduleClassWithclasskey:@"" subject:workingEnrollment.subject classdate:[((LessonRecord2 *)[tmpnextlessonarray objectAtIndex:i+existingnoofclass]).datetime substringToIndex:11] classtime:tmpclasstime instructor:tmpinstructor classroom:tmpclassroom attendance:[self returnEnrollmentDefaultAttendanceWithDay:[((LessonRecord2 *)[tmpnextlessonarray objectAtIndex:i+existingnoofclass]).datetime substringToIndex:11]] makeupdate:@"" makeuptime:@"" makeupinstructor:@"" makeupclassroom:@"" makeupattendance:@"" classremarks:@"" allclassremarks:[self returnallclassremarkswithsubject:workingEnrollment.subject] action:@"Add" classtype:@"Class" leavenaturelistkey:@"0" lesson:newlesson sinstructor:tmpsinstructor makeupsinstructor:@"" locked:NO]];
            }
            
            
        }
    }else{
        workingEnrollment.noofclass=[NSString stringWithFormat:@"%lu",(unsigned long)FreeScheduleClassArray.count];
        UIAlertController *erroralert = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Class Enrollment"] message:[MyClass returntitlewithtitle:@"Some of the classes are beyond available calendar days"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [erroralert dismissViewControllerAnimated:YES completion:nil];
        }];
        
        [erroralert addAction:OKAction];
        [self presentViewController:erroralert animated:YES completion:nil];
    }
}

