-(void) deleteFreeScheduleClasswithNoOfClass:(long)noofclass
{
    [df setDateFormat:@"dd-MMM-yyyy HH:mm"];
    NSDate *checkdatetime;
    NSDate *lastdatetime=nil;
    long lastdateindex=0;
    long noofclassdeleted=0;
    
    FreeScheduleClass *freescheduleclassobject=[[FreeScheduleClass alloc]init];
    for (long i=0;i<noofclass;i++) {
        if ([self hasStartDateTBDclasseswithFreeScheduleClassArray:FreeScheduleClassArray]) {
            //delete TBD class
            noofclassdeleted+=1;
            for (long j=0; j<FreeScheduleClassArray.count; j++) {
                freescheduleclassobject=[FreeScheduleClassArray objectAtIndex:j];
                if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
                    if ([freescheduleclassobject.classdate isEqualToString:@"TBD"]) {
                        if ([freescheduleclassobject.action isEqualToString:@""] || [freescheduleclassobject.action isEqualToString:@"Edit"]) {
                            freescheduleclassobject.action=@"Delete";
                            break;
                        }else if ([freescheduleclassobject.action isEqualToString:@"Add"]) {
                            [FreeScheduleClassArray removeObjectAtIndex:j];
                            break;
                        }
                    }
                }
            }
        }else{
            //delete last schedule class
            //find last class
            lastdatetime=nil;
            lastdateindex=0;
            for (int k=0; k<FreeScheduleClassArray.count; k++) {
                freescheduleclassobject=[FreeScheduleClassArray objectAtIndex:k];
                if (![freescheduleclassobject.action isEqualToString:@"Delete"]) {
                    
                    if (![freescheduleclassobject.attendance isEqualToString:@"Extend"] || ![self hasExtendedClassWithDictionary:ExtendedClasskeyDictionary Classkey:freescheduleclassobject.classkey FreeScheduleClassarray:FreeScheduleClassArray]) {
                        if ([freescheduleclassobject.classtime isEqualToString:@"TBD"]) {
                            checkdatetime=[df dateFromString:[NSString stringWithFormat:@"%@ %@",freescheduleclassobject.classdate,@"23:59"]];
                        }else{
                            checkdatetime=[df dateFromString:[NSString stringWithFormat:@"%@ %@",freescheduleclassobject.classdate,freescheduleclassobject.classtime]];
                        }
                        
                        if (!lastdatetime) {
                            lastdatetime=checkdatetime;
                            lastdateindex=k;
                        }else{
                            if ([lastdatetime compare:checkdatetime]==NSOrderedAscending) {
                                lastdatetime=checkdatetime;
                                lastdateindex=k;
                            }
                        }
                    }
                }
            }
            
            //delete last schedule class
            if (lastdatetime) {
                noofclassdeleted+=1;
                freescheduleclassobject=[FreeScheduleClassArray objectAtIndex:lastdateindex];
                if ([freescheduleclassobject.action isEqualToString:@""] || [freescheduleclassobject.action isEqualToString:@"Edit"]) {
                    freescheduleclassobject.action=@"Delete";
                }else if ([freescheduleclassobject.action isEqualToString:@"Add"]) {
                    [FreeScheduleClassArray removeObjectAtIndex:lastdateindex];
                }
            }
        }
    }
    
    if (noofclassdeleted<noofclass) {
        workingEnrollment.noofclass=[NSString stringWithFormat:@"%ld",[workingEnrollment.noofclass intValue]+(noofclass-noofclassdeleted)];
        UIAlertController *missinginput = [UIAlertController alertControllerWithTitle:[MyClass returntitlewithtitle:@"Unable to remove some of the class"] message:[MyClass returntitlewithtitle:@"Some of the class time has been used to extend other class"] preferredStyle:UIAlertControllerStyleAlert];
        
        UIAlertAction *OKAction = [UIAlertAction actionWithTitle:[MyClass returntitlewithtitle:@"OK"] style:UIAlertActionStyleCancel handler:^(UIAlertAction *action) {
            [missinginput dismissViewControllerAnimated:YES completion:nil];
            
        }];
        
        [missinginput addAction:OKAction];
        //[self presentViewController:missinginput animated:YES completion:nil];
                    [MyClass presentViewController:missinginput View:self];
        
    }
}
- (UIView *)pickerView:(UIPickerView *)pickerView viewForRow:(NSInteger)row forComponent:(NSInteger)component reusingView:(UIView *)view
{
    UILabel* tView = (UILabel*)view;
    
    NSDateFormatter *df2=[[NSDateFormatter alloc]init];
    NSDate *date;
    if (!tView)
    {
        tView = [[UILabel alloc] init];
        tView.textAlignment=NSTextAlignmentCenter;
        [tView setFont:[UIFont systemFontOfSize:18]];
        tView.adjustsFontSizeToFitWidth=YES;
        tView.minimumScaleFactor=0.7;
        tView.numberOfLines=3;
    }
    
    if([selectedItem isEqualToString:@"DateTime"]){
        [tView setFont:[UIFont systemFontOfSize:16]];
        if (component==0){
            tView.text= [hourPickerViewMenu objectAtIndex:row];
        }else{
            tView.text= [minutePickerViewMenu objectAtIndex:row];
        }
    }else if([selectedItem isEqualToString:@"Level"]){
        if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
                if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                    tView.text= [levelmainPickerViewMenu objectAtIndex:row];
                }else{
                    if (component==0){
                        tView.text= [levelmainPickerViewMenu objectAtIndex:row];
                    }else{
                        tView.text= [levelctmPickerViewMenu objectAtIndex:row];
                    }
                }
        }else{
            tView.text= [pickerViewmenu objectAtIndex:row];
        }
    }else if([selectedItem isEqualToString:@"ClassTime"]){
        if (component==0){
            tView.text= [[hourPickerViewMenu objectAtIndex:row] isEqualToString:@"Multi"]||[[hourPickerViewMenu objectAtIndex:row] isEqualToString:@"TBD"]||[[hourPickerViewMenu objectAtIndex:row] isEqualToString:@"TBF"]? [MyClass returntitlewithtitle:[hourPickerViewMenu objectAtIndex:row]]:[hourPickerViewMenu objectAtIndex:row];
        }else{
            tView.text= [minutePickerViewMenu objectAtIndex:row];
        }
    }else if([selectedItem isEqualToString:@"DetailsPayment"]){
        tView.text= [MyClass returndateformatEEEDDMMMYYYYwithdateDDMMMYYYY:[MyClass returnDateFromBaseDateWithOffset:row]];
    }else if([selectedItem isEqualToString:@"PaidMethod"]){
            tView.text= [MyClass returntitlewithtitle:[pickerViewmenu objectAtIndex:row]];
    }else if([selectedItem isEqualToString:@"RefundMethod"]){
        tView.text= [MyClass returntitlewithtitle:[pickerViewmenu objectAtIndex:row]];
    }else if ([selectedItem isEqualToString:@"EndDate"]){
        if (row==0) {
            tView.text=@"";
        }else{
            
            long monthoffset=[MyClass returnMonthOffsetWithDate:[MyClass convertToNSDateWithDate:workingEnrollment.startdate DateFormat:@"dd-MMM-yyyy"]]-1;
            
            if ([globalvariables.language isEqualToString:@"English"]) {
                tView.text=[NSString stringWithFormat:@"End %@",[MyClass returnMonthFromBaseDateWithOffset:(row+monthoffset)]];
            }else{
                df2.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"en_US"];[df2 setDateFormat:@"MMM yyyy"];
                date=[df2 dateFromString:[MyClass returnMonthFromBaseDateWithOffset:(row+monthoffset)]];
                df2.locale=[[NSLocale alloc]initWithLocaleIdentifier:@"zh_CN"];[df2 setDateFormat:@"yyyy年M月底"];
                tView.text=[df2 stringFromDate:date];
            }
        }
    }else if([selectedItem isEqualToString:@"DLMakeupStartDateTime"] || [selectedItem isEqualToString:@"DLStartDateTime"]){
        if (component==0){
            tView.text= [hourPickerViewMenu objectAtIndex:row];
        }else{
            tView.text= [minutePickerViewMenu objectAtIndex:row];
        }
    }else if ([selectedItem isEqualToString:@"CSInstructor"]){
        if ([((Instructor *)[pickerViewmenu objectAtIndex:row]).firstname isEqualToString:@"TBD"]) {
            tView.text=[MyClass returntitlewithtitle:@"TBD"];
        }else{
            tView.text=[MyClass returninstructornamewithusername:((Instructor *)[pickerViewmenu objectAtIndex:row]).username firstorfullname:@"full"];
        }
    }else if ([selectedItem isEqualToString:@"CSClassroom"]){
        if ([((ClassroomRecord *)[pickerViewmenu objectAtIndex:row]).classroom isEqualToString:@"TBD"]) {
            tView.text=[MyClass returntitlewithtitle:@"TBD"];
        }else{
            tView.text= ((ClassroomRecord *)[pickerViewmenu objectAtIndex:row]).classroom;
        }
    }else if([selectedItem isEqualToString:@"CSClassTime"]){
        if (component==0){
            tView.text= [MyClass returntitlewithtitle:[dayPickerViewMenu objectAtIndex:row]];
        }else if (component==1){
            tView.text= [hourPickerViewMenu objectAtIndex:row];
        }else{
            tView.text= [minutePickerViewMenu objectAtIndex:row];
        }
    }else if([selectedItem isEqualToString:@"MakeupQuota"]){
        if ([[pickerViewmenu objectAtIndex:row] isEqualToString:@"-1"]){
            tView.text= [MyClass returntitlewithtitle:@"Unlimited"];
        }else{
            tView.text= [pickerViewmenu objectAtIndex:row];
        }
    }else if ([selectedItem isEqualToString:@"DLLessonNumber"]|| [selectedItem isEqualToString:@"StartingLesson"]){
        if (component==0) {
            tView.text= [((NSMutableArray *)lessonArray[0]) objectAtIndex:row];
        }else if (component==1) {
            tView.text= [((NSMutableArray *)lessonArray[1]) objectAtIndex:row];
        }else if (component==2) {
            tView.text= [@(row+1) stringValue];
        }else if (component==3) {
            tView.text= [@(row+1) stringValue];
        }
    }else if ([selectedItem isEqualToString:@"StandardPeriod"]) {
        if (component==0){
            tView.text= [MyClass returntitlewithtitle:[standardnoofclassormontharray objectAtIndex:row]];
        }else{
            tView.text= [MyClass returntitlewithtitle:[enrollmentmodearray objectAtIndex:row]];
        }
    }else{
        tView.text= [pickerViewmenu objectAtIndex:row];
    }
    
    //tView.text=[wishvalues objectAtIndex:row];
    return tView;
}


