- (CGFloat)tableView:(UITableView *)tableView heightForHeaderInSection:(NSInteger)section {
    if (tableView==sharetable) {
        return CGFLOAT_MIN;
    }else if (tableView==DetailsPaymentTable){
        
        if (section==1) {
            if ([((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).fcbrand isEqualToString:@"school"]) {
                return CGFLOAT_MIN;
            }
        }
        
        if (section==0) {
            return 44;
        }else if (section==1){
            return 44;
        }else{
            if (workingEnrollment.paymentrecords.count==0) {
                return 0;
            }else{
                return 44;
            }
        }
    }else if (tableView==EnrollmentPopoverTable){
        if ([EnrollmentTableMode isEqualToString:@"Add"]) {
            
            if (section==1){
                if (!globalvariables.centerrecord.enrollmentvalidity && !globalvariables.centerrecord.enablemakeupquota) {
                    return CGFLOAT_MIN;
                }
            }else if (section==2) {
                if ([((CenterSettings *)[MyClass returnCenterSettingswithCenterkey:globalvariables.centerrecord.centerkey]).fcbrand isEqualToString:@"school"]) {
                    return CGFLOAT_MIN;
                }
            }else if (section==4) {
                return showAutoRenew?44:0;
            }
            return 44;
            
        }else if ([EnrollmentTableMode isEqualToString:@"Edit"]){
            if (section==1){
                if (!globalvariables.centerrecord.enrollmentvalidity && !globalvariables.centerrecord.enablemakeupquota) {
                    return CGFLOAT_MIN;
                }
            }

            return 44;
        }else{
            if (section==1){
                if (!globalvariables.centerrecord.enrollmentvalidity && !globalvariables.centerrecord.enablemakeupquota) {
                    return CGFLOAT_MIN;
                }
            }
            return 44;
        }
    }else if (tableView==SubjectTable){
        return CGFLOAT_MIN;
    }else if (tableView==InstructorTable){
        return CGFLOAT_MIN;
    }else if (tableView==ScheduleTable){
        return CGFLOAT_MIN;
    }else if (tableView==ClassroomTable){
        return CGFLOAT_MIN;
    }else if (tableView==PromotionCodeTable){
        return CGFLOAT_MIN;
    }else if (tableView==CouponTable){
        return CGFLOAT_MIN;
    }else if (tableView==DLClassDateTable){
        return CGFLOAT_MIN;
    }else if (tableView==DLInstructorTable){
        return CGFLOAT_MIN;
    }else if (tableView==DLClassroomTable){
        return CGFLOAT_MIN;
    }else if (tableView==leaveNatureTable){
        return CGFLOAT_MIN;
    }else if (tableView==csInstructorTable){
        return CGFLOAT_MIN;
    }else if (tableView==csClassroomTable){
        return CGFLOAT_MIN;
    }else if (tableView==csClassDateTable){
        return CGFLOAT_MIN;
    }else if (tableView==DiscountTable){
        if (section==0) {
            return availablepromotionarray.count==0?CGFLOAT_MIN:44;
        }else if (section==2){
            return globalvariables.centerrecord.ecoupon?44:CGFLOAT_MIN;
        }
        return 44;
    }else if (tableView==csDayDateTimeTable){
        return CGFLOAT_MIN;
    }else{
        return 44;
    }
}

- (CGFloat)tableView:(UITableView *)tableView heightForFooterInSection:(NSInteger)section
{
    if (tableView==EnrollmentPopoverTable) {
        if (section==1){
            if (!globalvariables.centerrecord.enrollmentvalidity && !globalvariables.centerrecord.enablemakeupquota) {
                return CGFLOAT_MIN;
            }
        }else if ([tableView numberOfSections]-1==section) {
            return 30;
        }
    }else if (tableView==DiscountTable){
        if(section==0){
            return workingEnrollment.promotiondiscountrecords.count>0?CGFLOAT_MIN:38;
        }else if(section==2){
            return workingEnrollment.couponrecords.count>0?CGFLOAT_MIN:(globalvariables.centerrecord.ecoupon?38:0);
        }else if (section==3){
            return 30;
        }
    }else if (tableView==PromotionCodeTable){
        if (filteredavailablepromotionarray.count==0) {
            return 38;
        }else{
            return 30;
        }
    }else if (tableView==CouponTable){
        if (filteredavailablecouponarray.count==0) {
            return 38;
        }else{
            return 30;
        }
    }else if (tableView==InstructorTable){
        return 30;
    }else if (tableView==SubjectTable){
        return 30;
    }else if (tableView==VoidTable){
        return 30;
    }else if (tableView==ClassroomTable){
        return 30;
    }else if (tableView==ScheduleTable){
        return 60;
    }
    return CGFLOAT_MIN;
}

- (UIView *)tableView:(UITableView *)tableView viewForFooterInSection:(NSInteger)section {
    if (tableView==DiscountTable) {
        if (section==0) {
            if (availablepromotionarray.count>0) {
                if (workingEnrollment.promotiondiscountrecords.count==0) {
                    UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 38)];
                    header.backgroundColor=[UIColor whiteColor];
                    
                    UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(20, 0, tableView.frame.size.width-40, 38)];
                    label.text=[MyClass returntitlewithtitle:@"None"];
                    label.font=[UIFont systemFontOfSize:15];
                    label.numberOfLines=0;
                    label.textColor=[UIColor darkGrayColor];
                    [header addSubview:label];
                    
                    label=[[UILabel alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 0.4)];
                    label.backgroundColor=[UIColor lightGrayColor];
                    label.layer.opacity=0.3;
                    [header addSubview:label];
                    
                    label=[[UILabel alloc]initWithFrame:CGRectMake(0, header.frame.size.height, tableView.frame.size.width, 0.4)];
                    label.backgroundColor=[UIColor lightGrayColor];
                    label.layer.opacity=0.3;
                    [header addSubview:label];
                    
                    return header;
                }
            }
        }else if (section==2) {
            if (availablecouponarray.count>=0 && globalvariables.centerrecord.ecoupon) {
                if (workingEnrollment.couponrecords.count==0) {
                    UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 38)];
                    header.backgroundColor=[UIColor whiteColor];
                    
                    UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(20, 0, tableView.frame.size.width-40, 38)];
                    label.text=[MyClass returntitlewithtitle:@"None"];
                    label.font=[UIFont systemFontOfSize:15];
                    label.numberOfLines=0;
                    label.textColor=[UIColor darkGrayColor];
                    [header addSubview:label];
                    
                    label=[[UILabel alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 0.4)];
                    label.backgroundColor=[UIColor lightGrayColor];
                    label.layer.opacity=0.3;
                    [header addSubview:label];
                    
                    label=[[UILabel alloc]initWithFrame:CGRectMake(0, header.frame.size.height, tableView.frame.size.width, 0.4)];
                    label.backgroundColor=[UIColor lightGrayColor];
                    label.layer.opacity=0.3;
                    [header addSubview:label];
                    
                    return header;
                }
            }
        }
    }else if (tableView==PromotionCodeTable){
        if (filteredavailablepromotionarray.count==0) {
            UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 38)];
            header.backgroundColor=[UIColor whiteColor];
            
            UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(20, 0, tableView.frame.size.width-40, 38)];
            label.text=[MyClass returntitlewithtitle:@"None"];
            label.font=[UIFont systemFontOfSize:15];
            label.numberOfLines=0;
            label.textColor=[UIColor darkGrayColor];
            [header addSubview:label];
            
            label=[[UILabel alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 0.4)];
            label.backgroundColor=[UIColor lightGrayColor];
            label.layer.opacity=0.3;
            [header addSubview:label];
            
            label=[[UILabel alloc]initWithFrame:CGRectMake(0, header.frame.size.height, tableView.frame.size.width, 0.4)];
            label.backgroundColor=[UIColor lightGrayColor];
            label.layer.opacity=0.3;
            [header addSubview:label];
            
            return header;
        }
    }else if (tableView==CouponTable){
        if (filteredavailablecouponarray.count==0) {
            UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 38)];
            header.backgroundColor=[UIColor whiteColor];
            
            UILabel *label=[[UILabel alloc]initWithFrame:CGRectMake(20, 0, tableView.frame.size.width-40, 38)];
            label.text=[MyClass returntitlewithtitle:@"None"];
            label.font=[UIFont systemFontOfSize:15];
            label.numberOfLines=0;
            label.textColor=[UIColor darkGrayColor];
            [header addSubview:label];
            
            label=[[UILabel alloc]initWithFrame:CGRectMake(0, 0, tableView.frame.size.width, 0.4)];
            label.backgroundColor=[UIColor lightGrayColor];
            label.layer.opacity=0.3;
            [header addSubview:label];
            
            label=[[UILabel alloc]initWithFrame:CGRectMake(0, header.frame.size.height, tableView.frame.size.width, 0.4)];
            label.backgroundColor=[UIColor lightGrayColor];
            label.layer.opacity=0.3;
            [header addSubview:label];
            
            return header;
        }
    }
    return nil;
}

-(UITableViewCellEditingStyle)tableView:(UITableView *)tableView editingStyleForRowAtIndexPath:(NSIndexPath *)indexPath
{
    return UITableViewCellEditingStyleDelete;
}

- (BOOL)tableView:(UITableView *)tableView canMoveRowAtIndexPath:(NSIndexPath *)indexPath
{
    if (tableView==DiscountTable) {
        if (indexPath.section==0) {
            return ((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscount && !(!((PrivilegeRecord *)[MyClass returnprivilegerecordwithcenterkey:globalvariables.centerrecord.centerkey]).editdiscountifpaid && [PopoverEnrollment.paid floatValue]!=0&& ![EnrollmentTableMode isEqualToString:@"Renewal"]);
        }else if (indexPath.section==2) {
            return YES;
        }
    }
    return NO;
}

- (NSIndexPath *)tableView:(UITableView *)tableView targetIndexPathForMoveFromRowAtIndexPath:(NSIndexPath *)sourceIndexPath toProposedIndexPath:(NSIndexPath *)proposedDestinationIndexPath
{
    if( sourceIndexPath.section != proposedDestinationIndexPath.section )
    {
        return sourceIndexPath;
    }
    else
    {
        return proposedDestinationIndexPath;
    }
}

- (BOOL)tableView:(UITableView *)tableview shouldIndentWhileEditingRowAtIndexPath:(NSIndexPath *)indexPath {
    return NO;
}

- (void)tableView:(UITableView *)tableView moveRowAtIndexPath:(NSIndexPath *)fromIndexPath toIndexPath:(NSIndexPath *)toIndexPath {
    //do whatever u want after row has been moved
    if (toIndexPath.section==0 && (fromIndexPath.row !=toIndexPath.row)) {
        
        marketingobject=[workingEnrollment.promotiondiscountrecords objectAtIndex:fromIndexPath.row];
        [workingEnrollment.promotiondiscountrecords removeObjectAtIndex:fromIndexPath.row];
        [workingEnrollment.promotiondiscountrecords insertObject:marketingobject atIndex:toIndexPath.row];
        
        [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    }else if (toIndexPath.section==2 && (fromIndexPath.row !=toIndexPath.row)) {
        
        CouponRecord *coupon =[workingEnrollment.couponrecords objectAtIndex:fromIndexPath.row];
        [workingEnrollment.couponrecords removeObjectAtIndex:fromIndexPath.row];
        [workingEnrollment.couponrecords insertObject:coupon atIndex:toIndexPath.row];
        
        [self calculateTotalFeeWithEnrollmentFee:workingEnrollment.enrollmentfee TuitionFee:workingEnrollment.tuitionfee LateFee:workingEnrollment.latefee];
    }
}

