-(void) enableDropClass:(UISwitch *)sender
{
    if (sender.on==YES){
        if (!PopoverEnrollment || [PopoverEnrollment.dropclassstatus isEqualToString:@"No"] || [PopoverEnrollment.dropclassdate isEqualToString:@""]) {
            [df setDateFormat:@"dd-MMM-yyyy"];
            workingEnrollment.dropclassstatus=@"Yes";
            workingEnrollment.dropclassdate=[df stringFromDate:[NSDate date]];
        }else{
            workingEnrollment.dropclassstatus=@"Yes";
            workingEnrollment.dropclassdate=PopoverEnrollment.dropclassdate;
        }
        showDropClassDate=YES;
//        swAutoRenew.on=NO;
        workingEnrollment.autorenew=@"No";
    }else{
        workingEnrollment.dropclassstatus=@"No";
        workingEnrollment.dropclassdate=@"";
        showDropClassDate=NO;
    }
    
    //[self storeTmpField];
    [EnrollmentPopoverTable reloadData];
    [self adjusttablesize];
}

-(void) editdlvalue:(UIButton *)sender
{
    
    [self closeallenrollmentpickers];

    [EnrollmentPopoverTable reloadData];
    
    CGPoint point = [sender.superview convertPoint:CGPointZero toView:DetailLessonTable];
    NSIndexPath *indexPath =[DetailLessonTable indexPathForRowAtPoint:point];
    currentselectedfreescheduleclass=[FreeScheduleClassArray objectAtIndex:indexPath.row];


    if (selectedlessonrow==indexPath.row && selecteddlbutton==sender.tag%1100) {
        //close
        selectedlessonrow=-1;
        selecteddlbutton=-1;
    }else{
        //open
        selectedlessonrow=indexPath.row;
        selecteddlbutton=sender.tag % 1100;
    }
    
    if (selecteddlbutton==0 || selecteddlbutton==1 || selecteddlbutton==2) {
        selectedItem=@"DLStartDateTime";
        if ([currentselectedfreescheduleclass.classdate isEqualToString:@""] || [currentselectedfreescheduleclass.classdate isEqualToString:@"TBD"]) {
            //set to next working day time
            NSDate *date=[NSDate date];
            [df setDateFormat:@"dd-MMM-yyyy HH:mm"];

            lesson2object=[[MyClass findnextlessonwithdatetime:@""/*[df stringFromDate:[NSDate date]]*/ dayofweek:[MyClass returndayofweek:[df stringFromDate:date]] schedulerecord:[MyClass returnscheduleinformationwithsubject_shortname:workingEnrollment.subject schedulekey:workingEnrollment.schedulekey centerkey:globalvariables.centerrecord.centerkey] nooflesson:1 includebasedate:YES excludescheduleenddatecheck:YES manualselection:NO] firstObject];
            NSString *nextclassdatetime=lesson2object.datetime;
            
            NSString *nextclassdate=[nextclassdatetime substringToIndex:11];
            NSString *nextclasstime;
            if ([workingEnrollment.schedulekey intValue]>=0) {
                nextclasstime=[nextclassdatetime substringFromIndex:12];
                if(!nextclasstime){
                    nextclasstime=[NSString stringWithFormat:@"%@:%@",[globalvariables.centerrecord.classstarttime substringToIndex:2],[globalvariables.centerrecord.classstarttime substringFromIndex:2]];
                }
            }else{
                nextclasstime=[NSString stringWithFormat:@"%@:%@",[globalvariables.centerrecord.classstarttime substringToIndex:2],[globalvariables.centerrecord.classstarttime substringFromIndex:2]];
            }
            
            if ([currentselectedfreescheduleclass.classtime isEqualToString:@""] || [currentselectedfreescheduleclass.classtime isEqualToString:@"TBD"]) {
                [self updatefreescheduleclassobject:currentselectedfreescheduleclass classdate:nextclassdate classtime:nextclasstime instructor:nil classroom:nil attendance:nil makeupdate:nil makeuptime:nil makeupinstructor:nil makeupclassroom:nil makeupattendance:nil leavenaturelistkey:nil sinstructor:nil makeupsinstructor:nil sortschedule:YES];
                [DetailLessonTable reloadData];
                [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
                //[self storeTmpField];
                [self closeallenrollmentpickers];
                [EnrollmentPopoverTable reloadData];
            }else{
                [self updatefreescheduleclassobject:currentselectedfreescheduleclass classdate:nextclassdate classtime:nil instructor:nil classroom:nil attendance:nil makeupdate:nil makeuptime:nil makeupinstructor:nil makeupclassroom:nil makeupattendance:nil leavenaturelistkey:nil sinstructor:nil makeupsinstructor:nil sortschedule:YES];
                [DetailLessonTable reloadData];
                [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
                //[self storeTmpField];
                [self closeallenrollmentpickers];
                [EnrollmentPopoverTable reloadData];
            }
        }else{
            if ([currentselectedfreescheduleclass.classtime isEqualToString:@""] || [currentselectedfreescheduleclass.classtime isEqualToString:@"TBD"]) {
                [self updatefreescheduleclassobject:currentselectedfreescheduleclass classdate:nil classtime:[NSString stringWithFormat:@"%@:%@",[globalvariables.centerrecord.classstarttime substringToIndex:2],[globalvariables.centerrecord.classstarttime substringFromIndex:2]] instructor:nil classroom:nil attendance:nil makeupdate:nil makeuptime:nil makeupinstructor:nil makeupclassroom:nil makeupattendance:nil leavenaturelistkey:nil sinstructor:nil makeupsinstructor:nil sortschedule:YES];
                [DetailLessonTable reloadData];
                [self updateClassTimeEndDateClassDayInstructorWithFreeScheduleClassArray];
                //[self storeTmpField];
                [self closeallenrollmentpickers];
                [EnrollmentPopoverTable reloadData];
            }
        }
        
        if (selecteddlbutton==2) {
            DLStartDateTimeCarryOverButton.hidden=NO;
        }else{
            DLStartDateTimeCarryOverButton.hidden=NO;
        }
        //[DLClassDateTable reloadData];

    }else if (selecteddlbutton==3){
        selectedItem=@"DLInstructor";
        dlinstructortablesearchbar.text=@"";
        filteredAvailableInstructorArray=[[NSMutableArray alloc]initWithArray:AvailableInstructorArray];
        DLInstructorCarryOverButton.hidden=NO;
        //[DLInstructorTable reloadData];
    }else if (selecteddlbutton==4){
        selectedItem=@"DLClassroom";
        dlclassroomtablesearchbar.text=@"";
        FilteredClassroomArray=[[NSMutableArray alloc]initWithArray:AvailableClassroomArray];
        DLClassroomCarryOverButton.hidden=NO;
        //[DLClassroomTable reloadData];
