-(void) reformatdlbutton:(UIButton *)sender
{
    if ([DetailLessonMode isEqualToString:@"View"] || [PopoverEnrollment.status isEqualToString:@"Voided"]) {
        [sender setTitleColor:[UIColor darkGrayColor] forState:UIControlStateNormal];
        sender.userInteractionEnabled=NO;
    }else{//edit
        if ([((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).tuition_mode isEqualToString:@"Month"]) {
            if (sender.tag==1100 || sender.tag==1101 || sender.tag==1102) {
                if (globalvariables.centerrecord.editmonthlycourseclassdate && [self editPaidEnrollment]) {
                    [sender setTitleColor:[UIColor colorWithRed:0.0 green:122.0/255.0 blue:1.0 alpha:1.0] forState:UIControlStateNormal];
                    sender.userInteractionEnabled=YES;
                }else{
                    [sender setTitleColor:[UIColor darkGrayColor] forState:UIControlStateNormal];
                    sender.userInteractionEnabled=NO;
                }
            }else{
                [sender setTitleColor:[UIColor colorWithRed:0.0 green:122.0/255.0 blue:1.0 alpha:1.0] forState:UIControlStateNormal];
                sender.userInteractionEnabled=YES;
            }
        }else{
            if ([self editPaidEnrollment]) {
                [sender setTitleColor:[UIColor colorWithRed:0.0 green:122.0/255.0 blue:1.0 alpha:1.0] forState:UIControlStateNormal];
                sender.userInteractionEnabled=YES;
            }else{
                [sender setTitleColor:[UIColor darkGrayColor] forState:UIControlStateNormal];
                sender.userInteractionEnabled=NO;
            }
        }
    }
}

