-(NSString *) returnDateFromStartDate:(NSString *)date validity:(NSString *)validitystring
{
    if ([validitystring isEqualToString:@""]) {
        return date;
    }else{
        NSString *datestring;
        if ([[validitystring substringToIndex:1] isEqualToString:@"D"]) {
           
            int dayoffset=[[validitystring substringFromIndex:1] intValue];
            long startingindex=[MyClass returnDateOffsetWithDate:[MyClass convertToNSDateWithDate:date DateFormat:@"dd-MMM-yyyy"]]+1;
            
            for (long i=startingindex; dayoffset>0; i++) {
                datestring=[MyClass returnDateFromBaseDateWithOffset:i];
                if ([MyClass isWorkingDate:[MyClass convertToNSDateWithDate:datestring DateFormat:@"dd-MMM-yyyy"] includereserveddate:NO]) {
                    dayoffset-=1;
                }
            }
            return datestring;

        }else if ([[validitystring substringToIndex:1] isEqualToString:@"W"]) {
            int dayoffset=[[validitystring substringFromIndex:1] intValue];
            long startingindex=[MyClass returnDateOffsetWithDate:[MyClass convertToNSDateWithDate:date DateFormat:@"dd-MMM-yyyy"]]+7;
            
            for (long i=startingindex; dayoffset>0; i+=7) {
                datestring=[MyClass returnDateFromBaseDateWithOffset:i];
                if ([MyClass isWorkingDate:[MyClass convertToNSDateWithDate:datestring DateFormat:@"dd-MMM-yyyy"] includereserveddate:NO]) {
                    dayoffset-=1;
                }
            }
            return datestring;

        }else if ([[validitystring substringToIndex:1] isEqualToString:@"M"]) {
            int monthoffset=[[validitystring substringFromIndex:1] intValue];
            NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
            [dayComponent setMonth:monthoffset];
            [df setDateFormat:@"dd-MMM-yyyy"];
            NSCalendar *theCalendar = [NSCalendar currentCalendar];
            return [df stringFromDate:[theCalendar dateByAddingComponents:dayComponent toDate:[df dateFromString:date] options:0]];
        }else{// if ([[validitystring substringToIndex:1] isEqualToString:@"Y"]) {
            int yearoffset=[[validitystring substringFromIndex:1] intValue];
            NSDateComponents *dayComponent = [[NSDateComponents alloc] init];
            [dayComponent setYear:yearoffset];
            [df setDateFormat:@"dd-MMM-yyyy"];
            NSCalendar *theCalendar = [NSCalendar currentCalendar];
            return [df stringFromDate:[theCalendar dateByAddingComponents:dayComponent toDate:[df dateFromString:date] options:0]];
        }
    }
}

-(NSString *) returnvaliditylabel
{
    NSString *subjectvalidity=((SubjectRecord *)[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey]).validity;
    
    if ([workingEnrollment.validity isEqualToString:@""]) {
        if ([subjectvalidity isEqualToString:@""]) {
            return [MyClass returntitlewithtitle:@"Forever"];
        }else{
            if ([workingEnrollment.startdate isEqualToString:@""]) {
                return @"";
            }else{
                return [MyClass returntitlewithtitle:@"Forever"];
            }
        }
    }else{
        return [MyClass convertDateFormatWithDate:workingEnrollment.validity FromDateFormat:@"yyyy-MM-dd" ToDateFormat:@"dd-MMM-yyyy" Translate:YES];
    }
}

-(NSString *) returnvalidityvalue
{
    SubjectRecord *object=[MyClass returnsubjectinformationwithsubject_shortname:workingEnrollment.subject centerkey:globalvariables.centerrecord.centerkey];
    NSString *subjectvalidity=object.validity;
    
    if ([subjectvalidity isEqualToString:@""]) {
        return @"";
    }else{
        if ([workingEnrollment.startdate isEqualToString:@""] || [workingEnrollment.startdate isEqualToString:@"TBD"]) {
            if([object.tuition_mode isEqualToString:@"Class"]){
            return [MyClass convertDDMMMYYYYtoYYYYMMDDwithdate:[self returnDateFromStartDate:workingEnrollment.enrollmentdate validity:subjectvalidity]];;
            }else{
                return @"";
            }
        }else{
            return [MyClass convertDDMMMYYYYtoYYYYMMDDwithdate:[self returnDateFromStartDate:workingEnrollment.startdate validity:subjectvalidity]];;
        }
    }
}

