-(BOOL) cstimearrayisemptywithrow:(long)row
{
    if (![((ScheduleDetailsRecord *)[workingSchedule.daytimearray objectAtIndex:row]).dayofweek isEqualToString:@""]) {
        return FALSE;
    }
    return TRUE;
