-(BOOL) updateAllLaterEnrollmentsLevel
{

    NSString *tmplevelmain;
    NSString *tmplevelctm;
    
    if ([MyClass isEyeLevelMathWithSubject:workingEnrollment.subject]) {
            if ([tmpLevel isEqualToString:@""]) {
                tmplevelmain=@"TBD";
                tmplevelctm=@"";
            }else if ([tmpLevel isEqualToString:@"TBD"] || [tmpLevel isEqualToString:@"DT"]) {
                tmplevelmain=tmpLevel;
                tmplevelctm=@"";
            }else{
                NSRange range=[tmpLevel rangeOfString:@"/"];
                if (range.location==NSNotFound) {
                    tmplevelmain=[tmpLevel substringFromIndex:3];
                    tmplevelctm=@"";
                }else{
                    tmplevelmain=[tmpLevel substringWithRange:NSMakeRange(3, range.location-3)];
                    tmplevelctm=[tmpLevel substringFromIndex:range.location+4];
                }
            }
    }else{
        if ([tmpLevel isEqualToString:@""]) {
            tmplevelmain=@"TBD";
        }else{
            tmplevelmain=tmpLevel;
        }
        tmplevelctm=@"";
    }
    

    
    if (![tmplevelmain isEqualToString:PopoverEnrollment.levelmain] || ![tmplevelctm isEqualToString:PopoverEnrollment.levelctm]) {
        if ([self.delegate isDifferentLevelWithLaterEnrollmentWithStartDate:workingEnrollment.startdate enrollmentkey:PopoverEnrollment.enrollmentkey subject:workingEnrollment.subject levelmain:tmplevelmain levelctm:tmplevelctm studentkey:PopoverEnrollment.studentkey]) {
            return TRUE;
        }
    }
    return FALSE;
}

