-(BOOL) isOneQuotaAvailable
{
    NSInteger makeupQuota=[workingEnrollment.makeup_quota integerValue];
    NSInteger makeupQuotaUsed=[workingEnrollment.makeup_quota_used integerValue];
    
        NSInteger quotaNeeded=1;
        FreeScheduleClass *obj;

        for(int i=0;i<FreeScheduleClassArray.count;i++){
            obj=[FreeScheduleClassArray objectAtIndex:i];
            if([obj.attendance isEqualToString:@"Makeup"]){
                if([obj.action isEqualToString:@"Add"] || [obj.action isEqualToString:@"Edit"]){
                    if([MyClass quotaCountedWithLeaveNatureListKey:obj.leavenaturelistkey attendance:obj.attendance]){
                        quotaNeeded+=1;
                        if(makeupQuota-makeupQuotaUsed<quotaNeeded){
                            return NO;
                        }
                    }
                }
            }
        }
        return (makeupQuota-makeupQuotaUsed>=quotaNeeded);
    
}

-(BOOL) extraQuotaRequiredWithNewLeaveNatureListKey:(NSString *)key attendance:(NSString *)attendance
{
    if(globalvariables.centerrecord.enablemakeupquota && ![workingEnrollment.makeup_quota isEqualToString:@"-1"]){
        if([MyClass quotaCountedWithLeaveNatureListKey:key attendance:attendance]){
            return YES;
        }
    }
    return NO;
    
}

